sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?hazardType ?property ?value ?time ?dateTime
WHERE {
  ?hazard rdf:type ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard ?property ?value . }

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?time .
    OPTIONAL { ?time time:inXSDDateTime ?dateTime . }
  }
}
ORDER BY ?hazardType ?time ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  {
    ?place a ?class .
    ?class rdfs:subClassOf* kwg-ont:Region .
    ?place kwg-ont:hasName ?name .
  } UNION {
    ?place a usgs:PopulatedPlace .
    ?place kwg-ont:hasName ?name .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?stormType ?superType ?property ?value
WHERE {
  {
    # Query subclasses of NOAAHazardEvent that are storm-specific (Hurricane, Tropical, Winter, Thunderstorm)
    ?stormType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
    FILTER (CONTAINS(STR(?stormType), "Hurricane") || CONTAINS(STR(?stormType), "TropicalStorm") || CONTAINS(STR(?stormType), "WinterStorm") || CONTAINS(STR(?stormType), "Thunderstorm"))
  } UNION {
    # Query explicit StormTrack classes
    ?stormType rdfs:subClassOf* kwg-ont:StormTrack .
  }

  OPTIONAL { ?stormType rdfs:subClassOf ?superType . }
  OPTIONAL { ?stormType ?property ?value . }
}
ORDER BY ?stormType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?superType ?property ?value
WHERE {
  ?floodType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER(STR(?floodType) CONTAINS "Flood")
  OPTIONAL { ?floodType rdfs:subClassOf ?superType }
  OPTIONAL { ?floodType ?property ?value }
}
ORDER BY ?floodType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute ?propertyType
WHERE {
  ?climateAttribute rdf:type kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?climateAttribute rdfs:subClassOf* ?propertyType }
}
ORDER BY ?climateAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType }
  OPTIONAL { ?earthquakeType ?property ?value }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?impactProperty ?value
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .

  OPTIONAL {
    ?collection sosa:hasFeatureOfInterest ?hazardEvent .
    ?collection a kwg-ont:ImpactObservationCollection .
    ?collection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?impactProperty .
    ?observation ?prop2 ?value .
  }

  OPTIONAL {
    ?hazardEvent ?generalProp ?generalValue .
    FILTER(?generalProp != sosa:isFeatureOfInterestOf)
  }
}
ORDER BY ?hazardEvent ?impactProperty ?value

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?hazardAttrName ?hazardAttrValue ?place ?damagePropName ?impactTime
WHERE {
  # Identify Hurricane Hazard Events
  ?hurricane a kwg-ont:NOAAHurricane .

  # Retrieve hurricane-specific hazard attributes (general properties)
  OPTIONAL { ?hurricane ?hazardAttrName ?hazardAttrValue }

  # Retrieve attributes related to geographical places (spatial relations)
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?place }

  # Link Hurricane to Impact Observations via Collection
  OPTIONAL {
    ?collection sosa:hasFeatureOfInterest ?hurricane .
    ?collection sosa:hasMember ?impactObs .
    ?impactObs a kwg-ont:ImpactObservation .

    # Retrieve damage impact details (observable properties)
    OPTIONAL { ?impactObs sosa:observedProperty ?damagePropName }

    # Retrieve temporal data if available
    OPTIONAL { ?impactObs sosa:phenomenonTime ?impactTime }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?type ?deaths ?damageToInfrastructure ?affectedArea
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . 
             OPTIONAL { ?type rdfs:label ?typeName } }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
}
ORDER BY ?startDate ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?label }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "diabetic") ||
    CONTAINS(LCASE(STR(?attribute)), "obese")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard (COUNT(DISTINCT ?hazard) AS ?count) WHERE {
  { 
    ?hazard rdf:type kwgl-ont:HazardEvent .
    FILTER (CONTAINS(LCASE(STR(?hazard)), "earthquake"))
  } UNION {
    ?hazard rdf:type kwgl-ont:HazardType .
    FILTER (CONTAINS(LCASE(STR(?hazard)), "earthquake"))
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(?attribute) AS ?total_count) WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado") || CONTAINS(LCASE(STR(?attributeLabel)), "tornado"))
}
GROUP BY ()
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") ||
    CONTAINS(LCASE(STR(?attribute)), "degreeday")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?typeLabel ?startDate ?endDate ?deaths ?damage WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damage }

  OPTIONAL { 
    ?hazard kwgl-ont:hasHazardType ?type .
    OPTIONAL { ?type rdfs:label ?typeLabel }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?hazardName
  ?startDate
  ?endDate
  ?numberOfDeaths
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?affectedAreaInAcres
WHERE {
  # Identify Hazard Events (direct type or properties implying domain)
  {
    ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  }
  UNION {
    # Fallback to ensure subclass instances are captured if not typed as super class directly
    ?hazardEvent ?p ?o .
    FILTER (
      ?p IN (
        kwgl-ont:numberOfDeaths,
        kwgl-ont:damageToCropsInDollars,
        kwgl-ont:damageToInfrastructureInDollars,
        kwgl-ont:affectedAreaInAcres,
        kwgl-ont:hasStartDate,
        kwgl-ont:hasEndDate,
        kwgl-ont:hasName
      )
    )
  }

  # Retrieve available impact and event details as optional variables
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    (BOUND(?attributeLabel) && CONTAINS(LCASE(STR(?attributeLabel)), "hurricane"))
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?place ?hazardName ?startDate ?endDate 
       ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres ?tornadoDamagePlace
WHERE {
  ?hazard rdf:type kwgl-ont:Tornado .

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { 
    ?hazard kwgl-ont:hasName ?hazardName .
    ?hazard kwgl-ont:hasStartDate ?startDate .
    ?hazard kwgl-ont:hasEndDate ?endDate .
  }

  OPTIONAL { 
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars .
  }
  OPTIONAL { 
    ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars .
  }
  OPTIONAL { 
    ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres .
  }

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamagePlace .
  }
}
ORDER BY ?hazard ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardLabel ?startDate ?endDate ?placeName ?damageInfra ?areaAcres
WHERE {
  # Identify Hazard Events with a defined temporal extent
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .

  # Ensure the hazard is related to a geographical place
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place rdfs:label ?placeName }

  # Filter for storm-specific hazards (Classes and Hazard Types)
  # Includes specific classes: Hurricane, Tornado
  FILTER (
    EXISTS { ?hazard rdf:type kwgl-ont:Hurricane } || 
    EXISTS { ?hazard rdf:type kwgl-ont:Tornado } ||
    (
      OPTIONAL { ?hazard kwgl-ont:hasHazardType ?htype . ?htype rdfs:label ?typeLabel }
      FILTER (BOUND(?typeLabel) && CONTAINS(LCASE(STR(?typeLabel)), "storm"))
    )
  )

  # Retrieve damage details available on the hazard event
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?areaAcres }

  OPTIONAL { ?hazard rdfs:label ?hazardLabel }
}
ORDER BY ?startDate ?placeName ?hazardLabel
