PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?hazardType ?affectedArea ?damageCrops ?damageInfra ?deaths
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}
ORDER BY ?startDate ?endDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (CONTAINS(LCASE(STR(?attribute)), "diabetic") || CONTAINS(LCASE(STR(?attribute)), "obese"))
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?label (SELECT (COUNT(?ht) AS ?total_count) WHERE {
  ?ht rdf:type kwgl-ont:HazardType .
  OPTIONAL { ?ht rdfs:label ?label }
  FILTER (CONTAINS(LCASE(STR(?ht)), "earthquake") || CONTAINS(LCASE(STR(?label)), "earthquake"))
}) AS ?total_count
WHERE {
  ?hazard rdf:type kwgl-ont:HazardType .
  OPTIONAL { ?hazard rdfs:label ?label }
  FILTER (CONTAINS(LCASE(STR(?hazard)), "earthquake") || CONTAINS(LCASE(STR(?label)), "earthquake"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?x) AS ?total_count)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))

  BIND((SELECT (COUNT(DISTINCT ?x2) WHERE { 
    ?x2 rdf:type owl:DatatypeProperty .
    FILTER(CONTAINS(LCASE(STR(?x2)), "tornado"))
  })) AS ?total_count))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") && 
    CONTAINS(LCASE(STR(?attribute)), "place")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazard
  ?name
  ?startDate
  ?endDate
  ?area
  ?cropDamage
  ?infraDamage
  ?deaths
  ?type
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . FILTER(?type = kwglr:earthquake) }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?property
  ?propertyLabel
  ?range
  ?parentProperty
  ?parentLabel
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  OPTIONAL { ?property rdfs:domain kwgl-ont:HazardEvent . }
  OPTIONAL { ?property rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?property rdfs:range ?range . }
  OPTIONAL { ?property rdfs:label ?propertyLabel . }

  OPTIONAL {
    ?property rdfs:subPropertyOf ?parentProperty .
    OPTIONAL { ?parentProperty rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?property)), "damage") ||
    CONTAINS(LCASE(STR(?propertyLabel)), "damage")
  )
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?hazardName ?placeName ?affectedArea ?cropDamage ?infraDamage ?deaths ?startDate ?endDate
WHERE {
  # Identify Tornado-specific hazards (either subclass or type property)
  { ?hazard rdf:type kwgl-ont:Tornado }
  UNION
  { ?hazard kwgl-ont:hasHazardType kwglr:tornado }

  # Ensure it is a HazardEvent instance
  ?hazard rdf:type kwgl-ont:HazardEvent .

  # Related to a Geographical Place
  ?hazard kwgl-ont:hasImpacted ?place .
  ?place rdf:type kwgl-ont:Place .

  # Retrieve Damage Details from the Hazard Event (Optional as they may vary)
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }

  # Retrieve Temporal Extent Details (Start and End Dates)
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  # Retrieve Names for Identification
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?author WHERE {
    ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?doi WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
    ?publication a coress-ont:Publication .
    ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author ?advisorName WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisorName .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?publication ?title ?fieldOfStudy
WHERE {
    ?publication a coress-ont:Publication .
    ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
    OPTIONAL {
        ?publication coress-ont:hasTitle ?title .
    }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?college ?university ?city
WHERE {
  ?college a coress-ont:College ;
           coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG(?timeDiff) AS ?averageTime)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:hasPublicationType ?publicationType ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate .
  BIND((?pubDate - ?subDate) AS ?timeDiff)
}
GROUP BY ?publicationType
ORDER BY DESC(?averageTime)
LIMIT 10

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?department a coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fname }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?name
WHERE {
  ?author a coresr-ont:Author .
  OPTIONAL { ?author coresr-ont:nameAsString ?name }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG((xsd:int)(?dateOfPublication - ?dateOfSubmission)) AS ?avgDays) ?typeAsString
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?dateOfSubmission ;
               coresr-ont:dateOfPublication ?dateOfPublication ;
               coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?typeAsString .
}
GROUP BY ?publicationType ?typeAsString
ORDER BY DESC(?avgDays)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent coresr-ont:associatedWith ?department .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?fnInstance .
    ?fnInstance a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department WHERE { 
  ?department a coresr-ont:Department . 
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?type
WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub (COUNT(DISTINCT ?dept) AS ?departmentCount)
WHERE {
  ?pub a coresr-ont:Publication .
  OPTIONAL { ?pub coresr-ont:hasTitle ?title } 

  # Find roles (Author or Contributor) associated with the publication
  { ?pub coresr-ont:submittedBy ?role . FILTER(?role a coresr-ont:Role) } 
  UNION 
  { ?pub coresr-ont:hasContributor ?role . FILTER(?role a coresr-ont:Role) }

  # Link Role to Agent (Person)
  ?role coresr-ont:isPerformedBy ?agent .

  # Link Agent to Department(s)
  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub ?title
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?dept (COUNT(?agent) AS ?count)
WHERE {
  ?dept a coresr-ont:Department .
  ?dept coresr-ont:hasAssociatedAgent ?agent .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contact .
    ?contact a coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?count)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?details ?time WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { ?hazard rdfs:label ?details }

  UNION { 
    ?hazard kwg-ont:hasTemporalScope ?time .
  }
  UNION { 
    ?obs a sosa:Observation ;
         sosa:phenomenonTime ?time ;
         sosa:hasFeatureOfInterest ?hazard .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?concern ?label
WHERE {
  # Health-related observable properties (Public Health and Vulnerability)
  VALUES (?propertyClass) {
    (kwg-ont:PublicHealthObservableProperty)
    (kwg-ont:VulnerabilityObservableProperty)
  }

  ?concern a ?propertyClass .
  OPTIONAL {
    ?concern rdfs:label ?label
  }

  # Link to geographical places via SOSA Observation
  {
    ?observation a sosa:Observation ;
                 sosa:observedProperty ?concern ;
                 sosa:hasFeatureOfInterest ?place .

    # Ensure the feature is a geographical region/place
    ?place a kwg-ont:Region .
  } UNION {
    # Support Observation Collections linked to places
    ?observationCollection a sosa:ObservationCollection ;
                           sosa:hasFeatureOfInterest ?place ;
                           sosa:observedProperty ?concern .

    ?place a kwg-ont:Region .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attributeName WHERE {
  ?attr a kwg-ont:CensusObservableProperty .
  ?obs sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?attr .
  ?place a geo:Feature .
  BIND(REPLACE(STR(?attr), "^.*#", "") AS ?attributeName)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?name (COUNT(?e) AS ?total_count) WHERE {
  ?hazard a kwg-ont:Earthquake .
  OPTIONAL { ?hazard kwg-ont:hasName ?name }
  { SELECT (COUNT(*) AS ?total_count) WHERE { ?e a kwg-ont:Earthquake } }
} GROUP BY ?hazard ?name ?total_count

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?label ?propertyType
WHERE {
  # Select Storm Track Observable Properties (Attributes)
  {
    ?attr a kwg-ont:StormTrackObservableProperty ;
          rdfs:label ?label .
  }

  UNION 

  # Select Storm Tracklet Observable Properties (Attributes)
  {
    ?attr a kwg-ont:StormTrackletObservableProperty ;
          rdfs:label ?label .
  }

  # Ensure these attributes are linked to storm hazards which are geographical places (Features)
  FILTER EXISTS {
    ?observation sosa:observedProperty ?attr ;
                 sosa:hasFeatureOfInterest ?hazard .
    ?hazard a geo:Feature .
  }

  BIND(?attr AS ?propertyType)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?hazardName ?disasterId ?observedProperty ?attributeDetails WHERE {
  # Identify Flood Hazard instances (specific subclasses or general NOAAHazardEvent if specific flood data exists)
  { ?hazard a kwg-ont:NOAAFlood } UNION { ?hazard a kwg-ont:NOAALakeshoreFlood } UNION { 
      # Fallback to base class if subtypes not explicitly instantiated, filtering by name patterns if available (not strictly in schema logic, so relying on types)
      ?hazard a kwg-ont:NOAAHazardEvent .
      FILTER(?hazard NOT IN (?floodSpecific)) 
  }

  # Retrieve basic hazard details (Attributes/Details related to geographical places via the Hazard Entity)
  OPTIONAL { ?hazard kwg-ont:hasDisasterName ?hazardName }
  OPTIONAL { ?hazard kwg-ont:noaaDisasterID ?disasterId }

  # Retrieve attributes via linked Observations where Flood is the FeatureOfInterest
  # Matches observations of NOAAHazardEvent (includes Floods) such as Impact or Magnitude Observations
  ?observationCollection sosa:hasMember ?observation .
  ?observation a sosa:Observation ; 
               sosa:observedProperty ?observedProperty ;
               sosa:hasFeatureOfInterest ?hazard .

  # Retrieve details of the observed property itself if available (or just the property URI)
  BIND(STR(?observedProperty) AS ?attributeDetails)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute
WHERE {
  ?attribute a kwg-ont:ClimateObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?earthquake ?hazardType (STR(?geometry) AS ?geometryDetails) WHERE {
  ?earthquake a kwg-ont:Earthquake .
  ?earthquake ?type ?hazardType .
  BIND(kwg-ont:Earthquake AS ?classType)
  OPTIONAL {
    ?earthquake kwg-ont:hasGeometry ?geometry .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?hurricaneType ?observableProperty ?propertyLabel ?geometry ?temporalData
WHERE {
  # Identify Hurricane Hazard Events (Specific Types and General Hazard)
  {?hurricane a kwg-ont:NOAAHurricane} UNION {?hurricane a kwg-ont:NOAAMarineHurricaneTyphoon} .

  # Retrieve Hurricane Type information
  ?hurricane rdfs:subClassOf* ?hurricaneType .

  # Link to Observable Properties via Observations (Damage Impact and Hazard Attributes)
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?hurricane ;
         sosa:observedProperty ?observableProperty .
    FILTER NOT EXISTS {?observableProperty a kwg-ont:Hazard} 
  }

  # Retrieve Observable Property Labels/URIs for "Attributes" (Magnitude, Impact)
  OPTIONAL {
    ?observableProperty rdfs:label ?propertyLabel ;
                        sosa:observedProperty* ?impactProp .
    # Specifically looking for Hurricane-relevant attributes like Magnitude or Impact
    FILTER(STRSTARTS(STR(?observableProperty), "http://example.org/kwg/ontology#") || STRSTARTS(STR(?observableProperty), "kwg-ont:Magnetude"))
  }

  # Retrieve Spatial Geometry (Related to geographical place)
  OPTIONAL { ?hurricane kwg-ont:hasGeometry ?geometry . }
  OPTIONAL { ?hurricane geo:hasDefaultGeometry ?geoGeom . BIND(?geoGeom AS ?geometry) }

  # Retrieve Temporal Data from Observations or Hazard Scope
  OPTIONAL { ?obs sosa:phenomenonTime ?temporalData . }
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalData . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?observation ?damageProperty WHERE {
  ?hazard a kwg-ont:NOAATornado .
  ?collection sosa:hasFeatureOfInterest ?hazard ;
              sosa:phenomenonTime ?time ;
              sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?damageProperty .
  ?damageProperty a kwg-ont:ImpactObservableProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?type ?startDate ?endDate ?deaths ?infrastructureDamage ?cropDamage ?area ?externalID
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:hasKWGEntity ?externalID }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "diabetic") ||
    CONTAINS(LCASE(STR(?attribute)), "obese")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:subPropertyOf ?parentProp . }
  OPTIONAL { ?parentProp rdfs:domain kwgl-ont:Place . }

  OPTIONAL { ?attribute rdfs:label ?label . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "population") ||
    CONTAINS(LCASE(STR(?attribute)), "household") ||
    CONTAINS(LCASE(STR(?attribute)), "poverty") ||
    CONTAINS(LCASE(STR(?attribute)), "diabetic") ||
    CONTAINS(LCASE(STR(?attribute)), "obese")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(?attr) AS ?total_count)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?total_count)
    WHERE {
      ?attr rdf:type owl:DatatypeProperty .
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado"))
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?label)), "storm") ||
    CONTAINS(LCASE(STR(?label)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (CONTAINS(LCASE(STR(?attribute)), "flood"))
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?label }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") || 
    CONTAINS(LCASE(STR(?attribute)), "degree")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?deaths ?area ?cropDamage ?infraDamage ?typeURI ?typeLabel
WHERE {
  # Identify earthquake hazards (either by class or hazard type property)
  {
    ?hazard rdf:type kwgl-ont:Earthquake .
  }
  UNION
  {
    ?hazard rdf:type kwgl-ont:HazardEvent .
    ?hazard kwgl-ont:hasHazardType kwglr:earthquake .
  }

  # Retrieve details (optional to ensure all hazards are returned even if some properties are missing)
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  # Retrieve hazard type details
  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?typeURI .
    OPTIONAL { ?typeURI rdfs:label ?typeLabel . }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?placeName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?startDate ?endDate
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:tornado .

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?place ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  # Filter for storm-specific hazards (Hurricane or Tornado classes)
  { ?event rdf:type kwgl-ont:Hurricane }
  UNION
  { ?event rdf:type kwgl-ont:Tornado }

  # Relationship to geographical place
  ?event kwgl-ont:hasImpacted ?place .

  # Temporal extent details
  ?event kwgl-ont:hasStartDate ?startDate .
  ?event kwgl-ont:hasEndDate ?endDate .

  # Damage details available on HazardEvent
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?label ?timeValue WHERE {
  VALUES (?class) { (kwg-ont:Hazard) }

  # Retrieve instances of Hazard or its subclasses
  ?hazard a kwg-ont:Hazard .

  # Optional: Get Label for details
  OPTIONAL { 
    ?hazard rdfs:label ?label .
  }

  # Retrieve Time Scope
  ?hazard kwg-ont:hasTemporalScope ?timeObj .

  # Handle direct Instant (if timeObj is an Instant with dateTime) OR Interval (with Beginning -> Instant)
  OPTIONAL { 
    {
      # Case 1: Direct link to DateTime via TemporalEntity/Instant properties where applicable
      ?timeObj time:inXSDDateTime ?timeValue .
    } UNION {
      # Case 2: Temporal Entity has a beginning which is an Instant with dateTime (e.g., Interval)
      ?timeObj time:hasBeginning ?instant .
      ?instant time:inXSDDateTime ?timeValue .
    }
  }
}

PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
SELECT ?place ?name WHERE {
  VALUES ?class { kwg-ont:AdministrativeRegion gnis:State gnis:County usgs:Feature } 
  ?place a ?class .
  OPTIONAL {
    ?place rdfs:label ?name .
  }
  OPTIONAL {
    ?place gnis:stateName ?name .
  }
  OPTIONAL {
    ?place gnis:countyName ?name .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?healthProperty
WHERE {
  # Retrieve Public Health Observable Properties (subclasses)
  {
    ?healthProperty rdfs:subClassOf kwg-ont:PublicHealthObservableProperty .
  }
  UNION
  # Retrieve Vulnerability Observable Properties (often linked to health concerns in this schema context)
  {
    ?healthProperty rdfs:subClassOf kwg-ont:VulnerabilityObservableProperty .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?label (COUNT(*) AS ?totalCount) WHERE {
  # Retrieve earthquake hazards (instances of Earthquake class)
  ?hazard rdf:type kwg-ont:Earthquake .

  # Optional label to describe "what" they are
  OPTIONAL { ?hazard rdfs:label ?label }

  # Subquery to calculate the total count across all results
  {
    SELECT (COUNT(?any) AS ?totalCount) WHERE {
      ?any rdf:type kwg-ont:Earthquake .
    }
  }
}
GROUP BY ?hazard ?label

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attributeUri ?attributeName ?locationURI ?locationName ?observationResult WHERE {
  # Identify storm-specific hazard attributes (Observable Properties) based on schema classes
  {
    ?attributeUri rdfs:subClassOf kwg-ont:StormTrackObservableProperty .
  } UNION {
    ?attributeUri rdfs:subClassOf kwg-ont:StormTrackletObservableProperty .
  }

  # Retrieve attribute labels for details
  OPTIONAL { 
    ?attributeUri rdfs:label ?attributeName . 
  }

  # Optional: Retrieve details (results) and geographical places linked via observations
  OPTIONAL {
    ?observation sosa:observedProperty ?attributeUri .

    # Observation results/details
    ?observation sosa:hasSimpleResult ?observationResult .

    # Link to geographical places (Features/Interests) as per schema patterns for hazards and features
    ?observation sosa:hasFeatureOfInterest ?locationURI .
    OPTIONAL { 
      ?locationURI rdfs:label ?locationName . 
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?hazard ?label ?geometry ?spatialRelation ?timeScope
WHERE {
  VALUES ?floodType { 
    kwg-ont:NOAAFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAACoastalFlood 
    kwg-ont:NOAALakeshoreFlood 
  }

  ?hazard rdf:type ?floodType .

  OPTIONAL { ?hazard rdfs:label ?label }
  OPTIONAL { ?hazard geo:hasGeometry ?geometry }
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?defaultGeometry }
  OPTIONAL { 
    ?hazard kwg-ont:spatialRelation ?spatialRelation .
    ?spatialRelation rdf:type ?placeType .
  }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeScope }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?attribute (IF(BOUND(?label), ?label, "Unknown Attribute") AS ?name)
WHERE {
  # Identify climate-specific attributes as subclasses or instances of ClimateObservableProperty
  {
    ?attribute rdfs:subClassOf|a kwg-ont:ClimateObservableProperty .
  }

  # Ensure these attributes are related to geographical places (US Climate Divisions) via observations
  ?observationResult sosa:observedProperty ?attribute .
  ?observationResult sosa:hasFeatureOfInterest kwg-ont:USClimateDivision .

  OPTIONAL { ?attribute rdfs:label ?label }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?earthquake ?label ?type
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  BIND("kwg-ont:Earthquake" AS ?type)
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?observation ?damageDetails ?temporalExtent ?geographicalPlace
WHERE {
  ?observation a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:hasSimpleResult ?damageDetails .

  ?hazard rdfs:subClassOf kwg-ont:NOAAHazardEvent ;
          a kwg-ont:NOAATornado ;
          kwg-ont:spatialRelation ?geographicalPlace .

  ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author WHERE {
  ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS {
    ?agent coress-ont:hasFamilyName ?fname .
  }
}
GROUP BY ?department
ORDER BY DESC(?count)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?publicationType
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:hasPublicationType ?publicationType .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  ?publication coresr-ont:hasTitle ?title .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication (COUNT(DISTINCT ?department) AS ?deptCount)
WHERE {
  ?publication coresr-ont:hasTitle ?title .
  {
    ?publication coresr-ont:submittedBy ?person .
  } UNION {
    ?person coresr-ont:contributedTo ?publication .
  }
  ?person coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?agent coresr-ont:associatedWith ?department .
  OPTIONAL {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo rdf:type coresr-ont:FamilyName .
  }
  FILTER (!BOUND(?contactInfo))
}
GROUP BY ?department
ORDER BY DESC(?count)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisorName
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisorName .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS {
    ?agent coress-ont:hasFamilyName ?familyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?detailProperty ?detailValue ?eventTime ?dateTimeString
WHERE {
  # Identify instances that are hazards or subclasses of Hazard
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  # Retrieve temporal information (when they happened)
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?eventTime .
    ?eventTime time:inXSDDateTime ?dateTimeString .
  }

  # Retrieve details associated with the hazard instances
  OPTIONAL {
    ?hazard ?detailProperty ?detailValue .
  }
}
ORDER BY ?hazard ?type ?eventTime ?dateTimeString

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeClass ?nameLabel
WHERE {
  VALUES ?root { geo:Feature kwg-ont:Region }
  ?placeClass rdfs:subClassOf* ?root .
  OPTIONAL { ?placeClass rdfs:label ?nameLabel . }
  FILTER(BOUND(?nameLabel))
}
ORDER BY ?placeClass ?nameLabel

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?healthAttribute ?label
WHERE {
  ?healthAttribute rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty .
  OPTIONAL {
    ?healthAttribute rdfs:label ?label .
  }
}
ORDER BY ?healthAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?attribute
WHERE {
  ?attribute rdfs:subClassOf* kwg-ont:CensusObservableProperty .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?name (COUNT(*) AS ?total)
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:label ?name }
}
GROUP BY ?hazard ?name
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?stormType ?superType ?property ?value
WHERE {
  ?stormType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?stormType rdfs:subClassOf ?superType }
  OPTIONAL { ?stormType ?property ?value }
}
ORDER BY ?stormType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?superType ?property ?value
WHERE {
  ?floodType rdfs:subClassOf* kwg-ont:Hazard .
  FILTER(STR(?floodType) CONTAINS "Flood")
  OPTIONAL { ?floodType rdfs:subClassOf ?superType }
  OPTIONAL { ?floodType ?property ?value . }
}
ORDER BY ?floodType ?property ?value

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute
WHERE {
  ?climateAttribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneClass ?geoAttribute ?impactDetails ?temporalData
WHERE {
  # Identify hurricane-specific hazard classes
  { 
    ?hurricaneClass rdfs:subClassOf+ kwg-ont:NOAAHurricane .
  } UNION {
    ?hurricaneClass rdfs:subClassOf+ kwg-ont:NOAAMarineHurricaneTyphoon .
  }

  # Find geographical place attributes (geometry or spatial relations) associated with the class
  OPTIONAL { 
    ?hurricaneClass geo:hasGeometry ?geoAttribute .
  }
  OPTIONAL { 
    ?hurricaneClass kwg-ont:spatialRelation ?geoAttribute .
  }

  # Find damage impact details (observable properties linked to observations of hazard events)
  OPTIONAL {
    ?impactDetails rdfs:subClassOf kwg-ont:ImpactObservableProperty .
  }

  # Find temporal data concepts available for hurricane observations
  OPTIONAL { 
    ?hurricaneClass a sosa:FeatureOfInterest .
    ?temporalData time:TemporalEntity .
  } UNION {
    # Link to observation collections that have phenomenonTime
    ?obsColl sosa:phenomenonTime ?temporalData .
    ?obsColl a kwg-ont:ImpactObservationCollection .
    ?hurricaneClass rdfs:subClassOf* kwg-ont:NOAAHazardEvent . # Link to Hazard Event type for generic association
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?damageDetail ?time ?place
WHERE {
  ?hazard rdf:type kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazard rdfs:subClassOf* kwg-ont:NOAATornado }

  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?damageProp ;
       sosa:hasSimpleResult ?damageDetail .

  ?damageProp rdfs:subClassOf* kwg-ont:ImpactObservableProperty .

  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time }
  OPTIONAL { ?obs sosa:resultTime ?time2 . BIND(?time2 AS ?time) }
  OPTIONAL { ?hazard kwg-ont:sfWithin ?place }
}

