PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?property ?value ?timeValue
WHERE {
  # Identify hazards (instances of Hazard or its subclasses)
  ?hazard a kwg-ont:Hazard .

  # Retrieve general details as property-value pairs
  OPTIONAL { ?hazard ?property ?value }

  # Retrieve time information
  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    FILTER NOT EXISTS { ?hazard a kwg-ont:Hazard . ?hazard rdfs:subClassOf* kwg-ont:NOAAHazardEvent } 
    # The above filter is to try and avoid double counting if inferred, but since I query instances, I just need the link.
    # Actually simpler: Try to get time literals from temporal entities
  }
  OPTIONAL {
     ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
     { 
       ?temporalEntity time:inXSDDateTime ?timeValue .
     } UNION {
       ?temporalEntity time:inXSDDate ?timeValue .
     } UNION {
       ?temporalEntity time:inXSDDateTimeStamp ?timeValue .
     }
  }
}
ORDER BY ?hazard ?property ?timeValue

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdfs:type/rdfs:subClassOf* geo:Feature .
  OPTIONAL { ?place rdfs:label ?name }
}
ORDER BY ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute ?superType ?property ?value
WHERE {
  # Find classes representing storm-specific observable properties (attributes)
  UNION {
    { ?attr rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty . FILTER(?attr != kwg-ont:StormTrackletObservableProperty) }
    { ?attr rdfs:subClassOf* kwg-ont:StormTrackObservableProperty . FILTER(?attr != kwg-ont:StormTrackObservableProperty) }
  }

  # Assign to variable
  BIND(?attr AS ?attribute)

  # Retrieve immediate supertype details
  OPTIONAL { ?attribute rdfs:subClassOf ?superType . }

  # Retrieve general attributes and values for details
  OPTIONAL { 
    ?attribute ?property ?value . 
    FILTER(?property != rdfs:subClassOf && ?property != rdf:type)
  }
}
ORDER BY ?attribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
