PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType }
  OPTIONAL { ?earthquakeType ?property ?value }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?detail ?label
WHERE {
  ?detail rdfs:subClassOf kwg-ont:ImpactObservableProperty .
  OPTIONAL { 
    ?detail rdfs:label ?label .
  }
}
ORDER BY ?detail

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneAttr ?hurricanePlace ?hurricaneTime ?impactDetail ?damageResult ?temporalData
WHERE {
  # Retrieve Hurricane-specific Hazard Attributes (Observable Properties) and related Place/Temporal data
  OPTIONAL {
    ?hurricaneAttr a kwg-ont:MagnitudeObservableProperty .
    ?hurricaneAttr rdfs:subClassOf* kwg-ont:Hazard .

    # Link to hazard instances for geographical place and temporal scope
    OPTIONAL {
      ?hazard a kwg-ont:NOAAHurricane .
      ?obs sosa:observedProperty ?hurricaneAttr .
      ?obs sosa:phenomenonTime ?hurricaneTime .

      ?hazard geo:hasGeometry ?hurricanePlace .
    } OR {
       # General hazard properties related to place via geometry or spatial relation
       OPTIONAL { 
         ?attrInstance a ?hurricaneAttr .
         ?attrInstance geo:hasGeometry ?hurricanePlace .
         ?attrInstance kwg-ont:spatialRelation ?hurricanePlace .
         ?attrInstance sosa:phenomenonTime ?hurricaneTime .
       }
    }
  }

  # Retrieve Damage Impact Details and Temporal Data
  OPTIONAL {
    ?impObs a kwg-ont:ImpactObservation .

    # Get the specific damage attribute observed (e.g., crop, property, death)
    ?impObs sosa:observedProperty ?impactProp .
    ?impactProp rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
    OPTIONAL { ?impactProp rdfs:label ?impactDetail }

    # Temporal data for impact observations
    ?impObs sosa:phenomenonTime ?temporalData .

    # Damage result details
    OPTIONAL { 
        ?impObs sosa:hasSimpleResult ?damageResult .
    }
  }
}
ORDER BY ?hurricaneAttr ?impactDetail

