PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?name ?when ?detailProp ?detailVal
WHERE {
  ?hazard a/kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?when }
  OPTIONAL { ?hazard rdfs:label ?name }
  OPTIONAL { ?hazard ?detailProp ?detailVal . FILTER(isLiteral(?detailVal)) }
}
ORDER BY ?hazard ?detailProp

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?property
WHERE {
  # Match observation collections linked to geographical places (Features)
  ?collection sosa:observedProperty ?property .
  ?collection sosa:hasFeatureOfInterest ?place .

  # Ensure the place is a geographical feature
  ?place rdfs:subClassOf* geo:Feature .

  # Filter for health-related observable properties (Public Health or Vulnerability)
  {
    ?property rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty .
  }
  UNION
  {
    ?property rdfs:subClassOf* kwg-ont:VulnerabilityObservableProperty .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?property (SELECT (COUNT(DISTINCT ?p) AS ?total_count) WHERE {
  {
    # Direct properties of Tornado instances
    ?hazard a kwg-ont:NOAATornado .
    ?hazard ?p ?value .
  } UNION {
    # Observable properties from observations of Tornadoes (e.g., magnitude, wind speed)
    ?observation sosa:hasFeatureOfInterest ?hazard .
    ?hazard a kwg-ont:NOAATornado .
    ?observation sosa:observedProperty ?p .
  }
}) AS ?total_count
WHERE {
  {
    # Direct properties of Tornado instances
    ?hazard a kwg-ont:NOAATornado .
    ?hazard ?property ?value .
  } UNION {
    # Observable properties from observations of Tornadoes (e.g., magnitude, wind speed)
    ?observation sosa:hasFeatureOfInterest ?hazard .
    ?hazard a kwg-ont:NOAATornado .
    ?observation sosa:observedProperty ?property .
  }
}
ORDER BY ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?stormType ?superType ?property ?value
WHERE {
  { ?stormType rdfs:subClassOf* kwg-ont:NOAAHazardEvent . }
  UNION
  { ?stormType rdfs:subClassOf* kwg-ont:StormTrack . }
  UNION
  { ?stormType rdfs:subClassOf* kwg-ont:StormTracklet . }

  OPTIONAL { ?stormType rdfs:subClassOf ?superType . }
  OPTIONAL { ?stormType ?property ?value . }
}
ORDER BY ?stormType ?property

