PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?state (COUNT(?pub) AS ?count)
WHERE {
  # Subquery A: Calculate publication counts for each university per state
  {
    SELECT ?university ?state (COUNT(?pub) AS ?count)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university a coress-ont:University ;
                  coress-ont:atState ?state .
    }
  }

  # Subquery B: Find the maximum publication count for each state
  {
    SELECT (MAX(?cnt) AS ?maxCount) ?st
    WHERE {
      SELECT DISTINCT ?u ?s ?c
      WHERE {
        ?pub a coress-ont:Publication .
        ?pub coress-ont:submittedBy ?author .
        ?author coress-ont:isPerformedBy ?agent .
        ?agent coress-ont:worksInDepartment ?department .
        ?department coress-ont:departmentOf ?college .
        ?college coress-ont:collegeOf ?university .
        ?university a coress-ont:University ;
                    coress-ont:atState ?s .
      }
      GROUP BY ?u ?s
    }
  }

  # Filter to keep only universities with the highest publication count for their state
  FILTER(?state = ?st && ?count = ?maxCount)
}
ORDER BY ?state ?university ?count DESC

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?dept (COUNT(?agent) AS ?count)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?dept .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fname }
}
GROUP BY ?dept
ORDER BY DESC(?count)
LIMIT 1

