  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?startDate ?endDate ?area ?damageToCrops ?damageToInfra ?deaths ?type
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfra }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?name ?attributeName ?attributeValue
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
  {
    ?place kwgl-ont:percentDiabetic ?attributeValue
    BIND("Health: Percent Diabetic" AS ?attributeName)
  } UNION {
    ?place kwgl-ont:percentObese ?attributeValue
    BIND("Health: Percent Obese" AS ?attributeName)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?property ?value WHERE {
  ?place rdf:type kwgl-ont:Place .
  VALUES (?property) { 
    (kwgl-ont:hasPopulation) 
    (kwgl-ont:hasNumberOfHouseHolds) 
    (kwgl-ont:percentBelowPovertyLine) 
    (kwgl-ont:percentDiabetic) 
    (kwgl-ont:percentObese) 
  }
  ?place ?property ?value .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard (COUNT(?hazard) AS ?count) WHERE {
  VALUES ?baseClass { kwgl-ont:Earthquake }
  OPTIONAL { ?hazard rdfs:subClassOf ?baseClass . FILTER (?hazard != ?baseClass) }
  OPTIONAL { ?hazard a owl:Class . FILTER (?hazard = kwgl-ont:Earthquake) }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (COUNT(?all_attributes) OVER() AS ?total_count) WHERE {
  kwgl-ont:Place ?attribute ?range .
  FILTER(CONTAINS(STR(?attribute), "Tornado"))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?name ?type ?area ?damageToCrops ?damageToInfrastructure WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasName ?name .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }

  ?hazardEvent kwgl-ont:hasHazardType ?type .

  FILTER (
    CONTAINS(LCASE(STRAFTER(STR(?type), "kwglr:")), "storm") ||
    STR(?type) = STR(kwglr:hurricane) ||
    STR(?type) = STR(kwglr:tornado)
  )

  ?place a kwgl-ont:Place .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardName ?hazardType ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?placeName WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwglr:flood, kwglr:flashFlood, kwglr:lakeshoreFlood, kwglr:coastalFlood))

  OPTIONAL {
    ?hazard kwgl-ont:hasName ?hazardName .
    ?hazard kwgl-ont:hasStartDate ?startDate .
    ?hazard kwgl-ont:hasEndDate ?endDate .
    ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres .
    ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars .
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars .
    ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths .
  }

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL {
    ?place kwgl-ont:hasName ?placeName .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?affectedArea ?cropsDamage ?infraDamage ?deaths ?kwgEntity ?type WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:hasKWGEntity ?kwgEntity }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?name ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
    ?hazardEvent rdf:type kwgl-ont:HazardEvent .
    OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
    OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
    OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?damageProperty ?damageValue
WHERE {
  ?place kwgl-ont:impactedBy ?hazard .
  ?hazard rdf:type kwgl-ont:HazardEvent .

  VALUES (?damageProperty) { 
    (kwgl-ont:damageToCropsInDollars) 
    (kwgl-ont:damageToInfrastructureInDollars) 
    (kwgl-ont:affectedAreaInAcres)
  } 

  ?hazard ?damageProperty ?damageValue .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT ?hurricane ?place ?name ?startDate ?endDate ?cropDamage ?infraDamage ?hurricaneDollarDamage WHERE {
  ?hurricane rdf:type kwgl-ont:Hurricane .
  ?hurricane kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?hurricane kwgl-ont:hasName ?name }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDollarDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?name ?startDate ?endDate ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres ?numberOfDeaths ?place WHERE {
    ?event rdf:type kwgl-ont:HazardEvent .
    ?event kwgl-ont:hasHazardType kwglr:tornado .
    ?event kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?event kwgl-ont:hasName ?name }
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
    OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
    OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazardEvent ?hazardName ?hazardType ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName }

  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasHazardType ?hazardType ;
                 rdfs:label ?typeLabel .
    BIND(?typeLabel AS ?hazardType) # Binding label as hazard type name for clarity, or keep URI if preferred. Using label for "details".
  }

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?label . }

  FILTER EXISTS { ?attribute rdfs:domain kwgl-ont:Place }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "population") ||
    CONTAINS(LCASE(STR(?attribute)), "household") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "poverty")
  )
}
ORDER BY ?label

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?name (COUNT(?x) AS ?totalCount) WHERE {
  VALUES (?hazard) { 
    SELECT DISTINCT ?x WHERE { ?x rdf:type kwgl-ont:Earthquake } 
  }
  OPTIONAL { ?hazard rdfs:label ?name }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?label }

  FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado") || CONTAINS(LCASE(?label), "tornado"))
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?property
  ?label
  ?range
  ?parentProperty
  ?parentLabel
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  OPTIONAL { ?property rdfs:domain kwgl-ont:HazardEvent . }
  OPTIONAL { ?property rdfs:range ?range . }
  OPTIONAL { ?property rdfs:label ?label . }

  OPTIONAL {
    ?property rdfs:subPropertyOf ?parentProperty .
    OPTIONAL { ?parentProperty rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?property)), "earthquake") ||
    CONTAINS(LCASE(STR(?label)), "earthquake")
  )
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?propertyLabel ?value
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL {
    { 
      ?hazard kwgl-ont:numberOfDeaths ?value . 
      kwgl-ont:numberOfDeaths rdfs:label ?propertyLabel . 
    }
    UNION
    { 
      ?hazard kwgl-ont:damageToCropsInDollars ?value . 
      kwgl-ont:damageToCropsInDollars rdfs:label ?propertyLabel . 
    }
    UNION
    { 
      ?hazard kwgl-ont:damageToInfrastructureInDollars ?value . 
      kwgl-ont:damageToInfrastructureInDollars rdfs:label ?propertyLabel . 
    }
    UNION
    { 
      ?hazard kwgl-ont:affectedAreaInAcres ?value . 
      kwgl-ont:affectedAreaInAcres rdfs:label ?propertyLabel . 
    }
  }
}
ORDER BY ?hazard ?propertyLabel

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?property ?label ?range
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  OPTIONAL { ?property rdfs:label ?label }
  OPTIONAL { ?property rdfs:range ?range }

  FILTER (
    CONTAINS(LCASE(STR(?property)), "damage") ||
    CONTAINS(LCASE(STR(?label)), "damage")
  )
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hurricaneAttribute ?hurricaneAttributeValue ?damageImpactType ?damageImpactValue ?temporalProperty ?temporalValue
WHERE {
  # Hurricane hazard event type or attributes related to hurricane
  {
    ?hurricaneAttr rdf:type owl:DatatypeProperty .

    OPTIONAL { ?hurricaneAttr rdfs:label ?hurricaneAttributeLabel }
    OPTIONAL { ?hurricaneAttr rdfs:domain kwgl-ont:HazardEvent }
    OPTIONAL { ?hurricaneAttr rdfs:range ?hurricaneAttributeValue }
  }

  UNION

  {
    # Hurricane-specific damage attributes (property names contain "hurricane")
    ?hurricaneAttr rdf:type owl:DatatypeProperty .
    FILTER(CONTAINS(LCASE(STR(?hurricaneAttr)), "hurricane"))
    OPTIONAL { ?hurricaneAttr rdfs:label ?hurricaneAttributeLabel }
  }

  # Get hurricane hazard events that impacted places
  {
    ?hazardEvent rdf:type kwgl-ont:Hurricane .
    ?hazardEvent kwgl-ont:hasImpacted ?place .

    OPTIONAL { 
      ?hazardEvent kwgl-ont:affectedAreaInAcres ?hurricaneAffectedArea .
      BIND(?hurricaneAffectedArea AS ?hurricaneAttributeValue)
    }

    OPTIONAL {
      ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamageValue .
      BIND("crops" AS ?damageImpactType)
      BIND(?cropDamageValue AS ?damageImpactValue)
    }

    OPTIONAL {
      ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamageValue .
      BIND("infrastructure" AS ?damageImpactType)
      BIND(?infraDamageValue AS ?damageImpactValue)
    }

    OPTIONAL {
      ?hazardEvent kwgl-ont:numberOfDeaths ?deathsValue .
      BIND("fatalities" AS ?damageImpactType)
      BIND(?deathsValue AS ?damageImpactValue)
    }

    OPTIONAL {
      ?hazardEvent kwgl-ont:hasStartDate ?startDate .
      BIND("start_date" AS ?temporalProperty)
      BIND(?startDate AS ?temporalValue)
    }

    OPTIONAL {
      ?hazardEvent kwgl-ont:hasEndDate ?endDate .
      BIND("end_date" AS ?temporalProperty)
      BIND(?endDate AS ?temporalValue)
    }
  }

  UNION

  {
    # Hurricane-specific place-level attributes (damage from hurricanes impacting places)
    ?hurricaneAttr rdf:type owl:DatatypeProperty .
    FILTER(CONTAINS(LCASE(STR(?hurricaneAttr)), "hurricane"))
    OPTIONAL { ?hurricaneAttr rdfs:label ?hurricaneAttributeLabel }

    # Get hurricane damage values for place-level attributes
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace* ?hurricaneValue .
    BIND(?hurricaneValue AS ?damageImpactValue)
    BIND("dollar_damage_hurricane" AS ?damageImpactType)

    OPTIONAL { 
      ?hurricaneAttr rdfs:label ?hurricaneAttributeLabel .
      FILTER(STRSTARTS(LCASE(STR(?hurricaneAttributeLabel)), "dollar damage of hurricanes"))
    }
  }

}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?damageCrops ?damageInfra ?deaths ?startDate ?endDate ?place ?placeLabel WHERE {
  ?hazard rdf:type kwgl-ont:Tornado .

  # Ensure hazard is related to a geographical place via 'hasImpacted' property
  ?hazard kwgl-ont:hasImpacted ?place .

  # Retrieve damage details (Optional as not all hazards may have all details recorded)
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }

  # Retrieve temporal extent details (Start and End dates)
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  # Retrieve place label for identification
  OPTIONAL { ?place rdfs:label ?placeLabel }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?type ?deaths ?infraDamage ?cropDamage ?area
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
}
ORDER BY ?startDate ?endDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?label (SELECT (COUNT(*) AS ?totalCount) WHERE { ?x rdf:type kwgl-ont:Earthquake }) AS ?totalCount
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:label ?label }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel (COUNT(?total) AS ?totalCount) WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
  FILTER(CONTAINS(LCASE(STR(?attribute)), "place"))

  { SELECT (COUNT(DISTINCT ?t) AS ?total) WHERE {
      ?t rdf:type owl:DatatypeProperty .
      FILTER(CONTAINS(LCASE(STR(?t)), "tornado"))
      FILTER(CONTAINS(LCASE(STR(?t)), "place"))
    } }
} GROUP BY ?attribute ?attributeLabel ?total ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
