PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?deaths ?damageToInfra ?area ?type
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfra }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?label . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?place ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres ?numberOfDeaths ?startDate ?endDate
WHERE {
  ?hazard rdf:type kwgl-ont:Tornado .

  ?hazard kwgl-ont:hasImpacted ?place .

  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }
}
ORDER BY ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?name ?label ?timeInfo
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?label }
  OPTIONAL { ?hazard skos:prefLabel ?skosLabel } 
  BIND(IF(BOUND(?skosLabel), ?skosLabel, ?label) AS ?name)
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    ?timeEntity time:inXSDDateTime ?dateStr .
    BIND(CONCAT("Occurs at: ", ?dateStr) AS ?timeInfo)
  }
  OPTIONAL {
    ?hazard kwg-ont:hasName ?name .
    FILTER(!BOUND(?name)) # Just in case name is different property
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?name WHERE {
  ?place a ?class .
  ?class rdfs:subClassOf* geo:SpatialObject .
  FILTER(?class != geo:Geometry && ?class != kwg-ont:Geometry) .
  OPTIONAL {
    ?place skos:prefLabel ?name .
  }
  OPTIONAL {
    ?place rdfs:label ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?geoPlaceURI ?concernPropertyURI (COALESCE(?concernLabel, "Unknown") AS ?concernLabel) WHERE {
  {
    ?obs a kwg-ont:PublicHealthObservation .
    ?obs sosa:hasFeatureOfInterest ?geoPlaceURI ;
         sosa:observedProperty ?concernPropertyURI .
  } UNION
  {
    ?obs a kwg-ont:VulnerabilityObservation .
    ?obs sosa:hasFeatureOfInterest ?geoPlaceURI ;
         sosa:observedProperty ?concernPropertyURI .
  }

  OPTIONAL { 
    ?concernPropertyURI rdfs:label ?concernLabel .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?label WHERE {
  ?attribute a kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?earthquake ?label (COUNT(?e) AS ?total_count) WHERE {
  { SELECT (COUNT(?e) AS ?total_count) WHERE { ?e a kwg-ont:Earthquake . } }

  ?earthquake a kwg-ont:Earthquake .

  OPTIONAL { 
    ?earthquake rdfs:label ?label .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?prop (COALESCE(?label, "Unlabeled") AS ?attributeName) 
       (SELECT(COUNT(DISTINCT ?p)) WHERE { ?p a kwg-ont:MagnitudeObservableProperty } AS ?totalAttributesCount)
WHERE {
  # Identify tornado-specific hazard attributes which are defined as Observable Properties in the KG schema
  ?prop a kwg-ont:MagnitudeObservableProperty .

  # Retrieve labels for identification
  OPTIONAL { 
    ?prop rdfs:label ?label .
  }
}
ORDER BY ASC(?attributeName)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?attribute ?label ?definition WHERE {
  VALUES ?propClass { kwg-ont:MagnitudeObservableProperty kwg-ont:ImpactObservableProperty kwg-ont:StormTrackObservableProperty }

  ?attribute rdf:type ?propClass .
  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute skos:definition ?definition }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?label ?geometryWKT ?temporalScope 
WHERE {
  # Identify flood-specific hazard types defined in the schema
  VALUES (?floodType) {
    (kwg-ont:NOAAFlood)
    (kwg-ont:NOAAFlashFlood)
    (kwg-ont:NOAACoastalFlood)
    (kwg-ont:NOAALakeshoreFlood)
  }

  # Find instances of these flood hazard types
  ?hazard a ?floodType .

  # Retrieve human-readable labels and definitions
  OPTIONAL {
    ?hazard rdfs:label ?label .
  }
  OPTIONAL {
    ?hazard skos:prefLabel ?label .
  }

  # Retrieve geographical details (Geometry/WKT) related to the hazard location
  OPTIONAL {
    ?hazard geo:asWKT ?geometryWKT .
  }
  OPTIONAL {
    ?hazard geo:hasDefaultGeometry [ 
      a geo:wktLiteral ;
      geo:asWKT ?geometryWKT .
    ] .
  }

  # Retrieve temporal attributes related to the hazard occurrence
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalScope .
    ?temporalScope time:hasBeginning ?startTime .
    ?temporalScope time:hasEnd ?endTime .
  }

  # Optional: Include narrative or other specific attributes defined for these hazards
  OPTIONAL {
    ?hazard kwg-ont:hasNarrative ?narrative .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?climateAttribute (IF(BOUND(?label), STR(?label), "Unknown") AS ?attributeName) WHERE {
  ?climateAttribute rdf:type kwg-ont:ClimateObservableProperty .
  OPTIONAL {
    ?climateAttribute rdfs:label ?label .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?type ?label
WHERE {
  ?hazard rdf:type kwg-ont:Earthquake .
  ?hazard rdf:type ?type .
  OPTIONAL { 
    ?hazard rdfs:label ?label .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?observation ?detailLabel WHERE {
  ?collection a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?hazard .

  ?collection sosa:hasMember ?observation .

  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?property .

  ?property rdfs:label ?detailLabel .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attributeLabel ?propertyTypeClass ?hazardLabel ?geoPlace ?temporalData
WHERE {
  # Find instances of Observable Properties (Hurricane attributes and Impact details)
  ?attr a sosa:ObservableProperty .
  ?attr rdfs:label ?attributeLabel .

  # Identify specific types for Hurricane Attributes and Impact Details
  ?attr rdf:type ?propertyTypeClass .

  FILTER(?propertyTypeClass IN (<kwg-ont:MagnitudeObservableProperty>, 
                               <kwg-ont:StormTrackObservableProperty>, 
                               <kwg-ont:ImpactObservableProperty>) || 
           CONTAINS(UCASE(STR(?attributeLabel)), "HURRICANE")) .

  # Link to Hazard Events (NOAAHazardEvent covers NOAA Hurricane)
  OPTIONAL {
    ?observation sosa:observedProperty ?attr ;
                 sosa:hasFeatureOfInterest ?hazard .
    FILTER(BOUND(?hazard)) .

    # Retrieve hazard details if available (including specific Hurricane instances)
    OPTIONAL { 
        ?hazard rdfs:label ?hazardLabel .
        ?hazard rdf:type kwg-ont:NOAAHazardEvent .
    }
  }

  # Temporal Data from Observations or Hazard Temporal Scope
  OPTIONAL { ?observation sosa:resultTime ?temporalData . }
  OPTIONAL { 
      ?hazard kwg-ont:hasTemporalScope ?temporalData .
      FILTER(BOUND(?temporalData))
  }

  # Geographical Place Relations (Spatial containment or relation)
  OPTIONAL { 
      ?hazard kwg-ont:sfWithin ?geoPlace .
  }
  OPTIONAL { 
      ?hazard kwg-ont:spatialRelation ?geoPlace .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetail WHERE {
  ?episode a kwg-ont:HazardEpisode .
  ?episode kwg-ont:hasNarrative ?damageDetail .
  ?episode kwg-ont:episodeHasPart ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .

  # Temporal extent constraint
  ?hazardEvent kwg-ont:hasTemporalScope ?temporalExtent .

  # Geographical place relation constraint (existential check via spatial properties)
  { 
    ?hazardEvent geo:spatialRelation ?geographicalPlace .
  } UNION
  { 
    ?hazardEvent kwg-ont:sfWithin ?geographicalPlace .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?timeValue WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?name }
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    OPTIONAL {
      ?temporalEntity a time:Instant .
      ?temporalEntity time:inXSDDateTime ?timeValue .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?place ?name WHERE {
  { 
    ?place a usgs:Feature .
    ?place rdfs:label ?name .
  }
  UNION
  { 
    ?place a usgs:Feature .
    ?place gnis:officialName ?name .
  }
  UNION
  { 
    ?place a gnis:State .
    ?place gnis:stateName ?name .
  }
  UNION
  { 
    ?place a gnis:County .
    ?place gnis:countyName ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?label (SELECT (COUNT(?e) AS ?total_count) WHERE { ?e a kwg-ont:Earthquake . } AS ?count_var)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?label WHERE {
  VALUES ?parent { kwg-ont:StormTrackletObservableProperty kwg-ont:StormTrackObservableProperty }
  ?attribute rdfs:subClassOf ?parent .
  OPTIONAL { ?attribute rdfs:label ?label }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?label ?geometry ?timeScope ?region
WHERE {
  VALUES ?floodType { kwg-ont:NOAAFlood kwg-ont:NOAACoastalFlood kwg-ont:NOAALakeshoreFlood kwg-ont:NOAAFlashFlood }
  ?hazard a ?floodType .

  OPTIONAL { ?hazard rdfs:label ?label }
  OPTIONAL { ?hazard geo:hasGeometry ?geometry }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeScope }
  OPTIONAL { 
    ?hazard kwg-ont:spatialRelation ?region .
    FILTER(?region != ?hazard)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute WHERE {
  ?attribute rdfs:subClassOf kwg-ont:ClimateObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>

SELECT ?earthquake ?typeClass ?typeName ?label ?description WHERE {
  ?earthquake a kwg-ont:Earthquake .

  # Retrieve the type (class) of the earthquake hazard
  ?earthquake rdf:type ?typeClass .
  OPTIONAL { ?typeClass rdfs:label ?typeName }

  # Retrieve details available on the feature instance
  OPTIONAL { ?earthquake rdfs:label ?label }
  OPTIONAL { ?earthquake gnis:description ?description }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?place ?attribute ?impactDetail ?temporalData
WHERE {
  # Identify Hurricane Hazard (specifically NOAAHurricane or related Hazard events)
  ?hazard a kwg-ont:NOAAHurricane .

  # Retrieve Geographical Place related to the hazard via spatial relation
  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    ?place a kwg-ont:AdministrativeRegion .
  }

  # Retrieve Hurricane-specific Hazard Attributes (Observable Properties) from observations of the hazard
  OPTIONAL {
    ?observation sosa:hasFeatureOfInterest ?hazard .
    ?observation sosa:observedProperty ?attribute .
  }

  # Retrieve Damage Impact Details linked to the hazard
  OPTIONAL {
    ?impact a kwg-ont:ImpactObservation .
    ?impact sosa:hasFeatureOfInterest ?hazard .
    ?impact sosa:hasSimpleResult ?impactDetail .
  }

  # Retrieve Temporal Data associated with the hazard or its observations
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalData .
  }
  OPTIONAL {
    ?observation sosa:phenomenonTime ?temporalData .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?type
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { 
    ?attribute rdfs:domain kwgl-ont:Place .
  }

  OPTIONAL { 
    ?attribute rdfs:label ?attributeLabel . 
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "diabetic") ||
    CONTAINS(LCASE(STR(?attribute)), "obese")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }

  OPTIONAL { 
    ?attribute rdfs:label ?label .
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "population") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "population") ||
    CONTAINS(LCASE(STR(?attribute)), "poverty") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "poverty")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquake (COUNT(?e) AS ?totalCount) WHERE {
  { SELECT ?e WHERE { ?e rdf:type kwgl-ont:Earthquake } }

  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL {
    ?earthquake kwgl-ont:hasName ?nameLabel .
    FILTER (BOUND(?nameLabel))
  }
}
GROUP BY ?earthquake ?totalCount

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?countLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?countLabel . }

  FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado"))

  # Ensure attributes are related to geographical places
  # This checks if the property has Place as domain, or is specifically named/place-based in this schema context.
  OPTIONAL { 
    ?attribute rdfs:domain kwgl-ont:Place . 
  }
  FILTER EXISTS {
     # Check if there is any connection indicating it relates to Places
     # Based on schema, properties impacting places are defined for kwgl-ont:Place
     ?place ?attribute xsd:nonNegativeInteger . 
     OPTIONAL { ?place rdf:type kwgl-ont:Place . }
  }

}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (CONTAINS(LCASE(STR(?attribute)), "flood"))

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?label . }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:range ?range }
  OPTIONAL { ?attribute rdfs:label ?label }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") ||
    CONTAINS(LCASE(STR(?attribute)), "degree")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?deaths ?area ?damageInfra ?damageCrops ?hazardType ?hazardTypeLabel WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }

  ?hazard kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?property
  ?propertyLabel
  ?range
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  OPTIONAL { ?property rdfs:domain kwgl-ont:HazardEvent . }
  OPTIONAL { ?property rdfs:label ?propertyLabel . }
  OPTIONAL { ?property rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?property)), "damage") ||
    CONTAINS(LCASE(STR(?property)), "deaths") ||
    CONTAINS(LCASE(STR(?property)), "area")
  )
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?damageProperty
  ?damageLabel
  ?range
WHERE {
  ?damageProperty rdf:type owl:DatatypeProperty .

  OPTIONAL { ?damageProperty rdfs:domain kwgl-ont:HazardEvent . }
  OPTIONAL { ?damageProperty rdfs:label ?damageLabel . }
  OPTIONAL { ?damageProperty rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?damageProperty)), "damage") ||
    CONTAINS(LCASE(STR(?damageLabel)), "damage")
  )
}
ORDER BY ?damageProperty

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?range
  ?domain
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:domain ?domain . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?hazard ?startDate ?endDate ?cropsDamage ?infraDamage ?tornadoDamageValue
WHERE {
  # Select Tornado Hazard Events related to a Place
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:tornado .

  # Link the hazard to the geographical place it impacted
  ?place kwgl-ont:impactedBy ?hazard .

  # Retrieve temporal extent details (start/end dates)
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  # Retrieve damage details available on the Hazard Event
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }

  # Retrieve specific Tornado Damage details related to the Place (including yearly variations)
  # Selecting base property as it is a superproperty of yearly variants or general damage summary
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamageValue .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?state ?pubCount
WHERE {
  {
    SELECT (COUNT(?publication) AS ?pubCount) ?state ?university
    WHERE {
      ?publication a coress-ont:Publication .
      ?publication coress-ont:submittedBy ?author .
      ?author coress-ont:worksInDepartment ?department .
      ?department coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?university ?state
  }
  FILTER(?pubCount = (SELECT MAX(subPubCount) { 
    SELECT (COUNT(?subPub) AS subPubCount) ?s WHERE {
      ?subPublication a coress-ont:Publication .
      ?authorSub coress-ont:submits ?subPublication .
      OPTIONAL{?authorSub coress-ont:worksInDepartment ?deptSub . ?deptSub coress-ont:departmentOf ?colSub . ?colSub coress-ont:collegeOf ?uni . ?uni coress-ont:atState ?s} 
    } GROUP BY ?s))
  )
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS {
    ?agent coress-ont:hasFamilyName ?fname
  }
}
GROUP BY ?department
ORDER BY DESC(?count)
LIMIT 1

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?startDate ?endDate ?affectedArea ?damageCrops ?damageInfra ?deaths ?hazardType
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attribute ?value WHERE {
  ?place a kwgl-ont:Place .
  VALUES (?attribute) { (kwgl-ont:percentDiabetic) (kwgl-ont:percentObese) }
  ?place ?attribute ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?attributeName ?value
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?property ?value .
  FILTER(?property IN (kwgl-ont:hasPopulation, kwgl-ont:hasNumberOfHouseHolds, kwgl-ont:percentBelowPovertyLine, kwgl-ont:percentDiabetic, kwgl-ont:percentObese))
  OPTIONAL { ?property rdfs:label ?attributeName }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?property (COUNT(?property) AS ?countOfProperties) WHERE {
  ?property a owl:DatatypeProperty .
  ?property rdfs:domain kwgl-ont:Place .
  OPTIONAL { ?property rdfs:label ?label }
  FILTER(CONTAINS(LCASE(STR(?property)), "tornado") || CONTAINS(LCASE(STR(?label)), "tornado"))
} GROUP BY ?property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?hazardEventName ?startDate ?endDate ?affectedArea ?stormDamage ?stormCount
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  # Link Place to Hazard Event (Place is impacted by Hazard Event)
  ?hazardEvent kwgl-ont:impactedBy ?place .

  # Get Hazard Event details
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardEventName }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea }

  # Get Storm-specific attributes on the Place
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormDamage }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?stormCount }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?floodAttribute ?attributeValue
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarValue .
    BIND("Dollar Damage of Floods Impacting Place" AS ?floodAttribute)
    BIND(?dollarValue AS ?attributeValue)
  }
  UNION
  {
    ?place kwgl-ont:numberOfFloodsImpactingPlace ?countValue .
    BIND("Number of Floods Impacting Place" AS ?floodAttribute)
    BIND(?countValue AS ?attributeValue)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?startDate ?endDate ?typeLabel WHERE {
  ?hazard a kwgl-ont:Earthquake .
  ?hazard kwgl-ont:hasName ?name .
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  ?hazard kwgl-ont:hasHazardType ?type .
  ?type rdfs:label ?typeLabel .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?name ?startDate ?endDate ?area ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hurricane ?place ?startDate ?endDate ?cropDamage ?infraDamage ?dollarDamage ?count
WHERE {
  ?hurricane rdf:type kwgl-ont:Hurricane .
  ?hurricane kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?count }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?placeName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?temporalStart ?temporalEnd
WHERE {
  ?event a kwgl-ont:Tornado .

  # Temporal Extent Filter (using variables for the extent)
  ?event kwgl-ont:hasStartDate ?start ;
         kwgl-ont:hasEndDate ?end .
  FILTER (?start >= ?temporalStart && ?end <= ?temporalEnd)

  # Relation to Place
  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  # Damage Details (Optional as they might not exist for all events)
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?event ?damageCrops ?damageInfra ?placeName ?startDate ?endDate
WHERE {
  # Identify storm-specific hazards (Class or Type)
  {
    ?event a kwgl-ont:Hurricane .
  } UNION {
    ?event a kwgl-ont:Tornado .
  } UNION {
    ?event kwgl-ont:hasHazardType ?stormType .
    FILTER(?stormType IN (kwglr:hurricane, kwglr:tropicalStorm, kwglr:stormSurgeTide))
  }

  # Damage details available on the HazardEvent
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops } .
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra } .

  # Temporal extent information (Start and End dates)
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate } .
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate } .

  # Related to a geographical place via hasImpacted property
  ?event kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName } .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author WHERE {
  ?author rdf:type coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication (COUNT(DISTINCT ?department) AS ?count)
WHERE {
  ?publication a coresr-ont:Publication .

  { 
    # Publications with Authors
    ?publication coresr-ont:submittedBy ?agent .
  } UNION {
    # Publications with Contributors
    ?publication coresr-ont:hasContributor ?agent .
  }

  ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?department a coresr-ont:Department .
  ?department coresr-ont:hasAssociatedAgent ?agent .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?count)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?startDate ?endDate ?deaths ?damageToInfrastructure ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  VALUES ?property { kwgl-ont:percentDiabetic kwgl-ont:percentObese }
  ?place ?property ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardName (SELECT (COUNT(?e) AS ?total_count) WHERE { ?e a kwgl-ont:Earthquake }) AS ?count
WHERE {
  ?hazard a kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?property (SELECT (COUNT(DISTINCT ?prop) AS ?count) WHERE {
  ?place a kwgl-ont:Place .
  ?place ?prop ?value .
  FILTER(CONTAINS(STR(?prop), "Tornado"))
}) AS ?total_count WHERE {
  ?place a kwgl-ont:Place .
  ?place ?property ?value .
  FILTER(CONTAINS(STR(?property), "Tornado"))
} GROUP BY ?property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?place ?attributeName ?value ?placeName
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?attribute ?value .
  FILTER(CONTAINS(STR(?attribute), "StormSurge") || CONTAINS(STR(?attribute), "Hurricane"))
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name 
       ?numberOfFloodsImpactingPlace 
       ?numberOfFloodsImpactingPlace2018 ?numberOfFloodsImpactingPlace2019 ?numberOfFloodsImpactingPlace2020 ?numberOfFloodsImpactingPlace2021 ?numberOfFloodsImpactingPlace2022
       ?dollarDamageOfFloodsImpactingPlace 
       ?dollarDamageOfFloodsImpactingPlace2018 ?dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace2020 ?dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace2022
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }

  # Flood-specific attributes on Place (Counts)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?numberOfFloodsImpactingPlace2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?numberOfFloodsImpactingPlace2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?numberOfFloodsImpactingPlace2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?numberOfFloodsImpactingPlace2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?numberOfFloodsImpactingPlace2022 }

  # Flood-specific attributes on Place (Damages)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?dollarDamageOfFloodsImpactingPlace2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?dollarDamageOfFloodsImpactingPlace2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?dollarDamageOfFloodsImpactingPlace2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?damageToInfrastructure ?affectedArea
WHERE {
    ?hazard a kwgl-ont:Earthquake .
    ?hazard kwgl-ont:hasName ?name .
    OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
    OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
    OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?name ?hazardType ?startDate ?endDate ?numberOfDeaths ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageDetail ?entity WHERE {
  {
    # Direct damage details on HazardEvents
    ?hazard a kwgl-ont:HazardEvent .
    ?hazard ?prop ?damageDetail .
    FILTER(CONTAINS(STR(?prop), "Damage") || CONTAINS(STR(?prop), "Deaths"))
  } UNION {
    # Damage details on Places impacted by HazardEvents
    ?place a kwgl-ont:Place .
    ?place kwgl-ont:impactedBy ?hazard .
    ?hazard a kwgl-ont:HazardEvent .
    ?place ?prop ?damageDetail .
    FILTER(CONTAINS(STR(?prop), "Damage") || CONTAINS(STR(?prop), "Deaths"))
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hurricane ?hurricaneName ?startDate ?endDate ?deaths ?infraDamage ?cropDamage ?areaAcres 
       ?place ?placeName ?phc ?pdd ?pd2018 ?pd2019 ?pd2020 ?pd2021 ?pd2022
       ?nhc ?n2018 ?n2019 ?n2020 ?n2021 ?n2022
WHERE {
  ?hurricane a kwgl-ont:Hurricane .
  ?hurricane kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane kwgl-ont:hasName ?hurricaneName }
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres ?areaAcres }

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?phc }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?pdd }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?pd2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?pd2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?pd2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?pd2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?pd2022 }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?n2018 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?n2019 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?n2020 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?n2021 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?n2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?place ?damageToInfrastructureInDollars ?damageToCropsInDollars ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace ?startDate ?endDate WHERE {
    ?hazard a kwgl-ont:Hurricane ;
            a kwgl-ont:Tornado .
    ?hazard kwgl-ont:hasStartDate ?startDate ;
            kwgl-ont:hasEndDate ?endDate .
    ?hazard kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
    OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace }
}

