PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?name ?startDate ?endDate ?typeLabel ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }

  OPTIONAL {
    ?hazardEvent kwgl-ont:hasHazardType ?type .
    OPTIONAL { ?type rdfs:label ?typeLabel }
  }

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }
}
ORDER BY ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label (COUNT(?subAttr) AS ?total_count) WHERE {
  # Subquery to calculate the total number of matching attributes
  {
    SELECT (COUNT(?subAttr) AS ?total_count) WHERE {
      ?subAttr rdf:type owl:DatatypeProperty .
      ?subAttr rdfs:domain kwgl-ont:Place .
      OPTIONAL { ?subAttr rdfs:label ?subLabel }
      FILTER (CONTAINS(LCASE(STR(?subAttr)), "tornado") || (BOUND(?subLabel) && CONTAINS(LCASE(STR(?subLabel)), "tornado")))
    }
  }

  # Main query to retrieve the attributes and their labels
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .
  OPTIONAL { ?attribute rdfs:label ?label }
  FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado") || (BOUND(?label) && CONTAINS(LCASE(STR(?label)), "tornado")))
} GROUP BY ?attribute ?label

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:range ?range }
  OPTIONAL { ?attribute rdfs:label ?label }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?label)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquake ?name ?hazardTypeLabel ?affectedArea ?deaths ?startDate ?endDate
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }

  OPTIONAL {
    ?earthquake kwgl-ont:hasHazardType ?hazardType .
    OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel }
  }

  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
}
ORDER BY ?earthquake

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?hazardType ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}
ORDER BY ?event

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?property
  ?label
  ?domain
  ?range
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  OPTIONAL { ?property rdfs:label ?label . }
  OPTIONAL { ?property rdfs:domain ?domain . }
  OPTIONAL { ?property rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?property)), "damage") ||
    CONTAINS(LCASE(STR(?label)), "damage")
  )
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?label . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?label)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?place ?affectedArea ?cropDamage ?infraDamage ?deaths ?startDate ?endDate
WHERE {
  ?event rdf:type kwgl-ont:Tornado .

  ?event kwgl-ont:hasImpacted ?place .

  ?event kwgl-ont:hasStartDate ?startDate .
  ?event kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazardEvent ?placeName ?damageCrops ?damageInfra ?eventStart ?eventEnd
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  # Filter for storm-specific hazards via HazardType labels or Classes
  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
    ?hazardType rdfs:label ?typeLabel .
    FILTER (CONTAINS(LCASE(STR(?typeLabel)), "storm") || CONTAINS(LCASE(STR(?typeLabel)), "hurricane") || CONTAINS(LCASE(STR(?typeLabel)), "tornado"))
  }

  # Temporal Extent Filter (using variables for the extent)
  ?hazardEvent kwgl-ont:hasStartDate ?eventStart .
  ?hazardEvent kwgl-ont:hasEndDate ?eventEnd .
  FILTER (?eventStart >= ?startDate && ?eventEnd <= ?endDate)

  # Damage Details
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageInfra }

  # Related Place
  ?hazardEvent kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place rdfs:label ?placeName }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?detailProperty ?detailValue ?date
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?name }
  OPTIONAL { ?hazard ?detailProperty ?detailValue . FILTER(?detailProperty != rdf:type && ?detailProperty != rdfs:subClassOf) }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalEntity . ?temporalEntity time:inXSDDateTime ?date }
}
ORDER BY ?hazard ?detailProperty ?date

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?healthConcern ?label
WHERE {
  ?healthConcern rdfs:subClassOf kwg-ont:PublicHealthObservableProperty .
  OPTIONAL { ?healthConcern rdfs:label ?label }
}
ORDER BY ?healthConcern

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdfs:subClassOf kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}
ORDER BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake (COUNT(?earthquake) OVER () AS ?total_count) ?label
WHERE { 
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?stormAttribute ?superType ?property ?value
WHERE {
  # Identify storm-specific hazard attributes (Observable Properties) related to StormTrack or StormTracklet
  { ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackObservableProperty }
  UNION
  { ?stormAttribute rdfs:subClassOf* kwg-ont:StormTrackletObservableProperty }

  # Retrieve super types for hierarchy details
  OPTIONAL { ?stormAttribute rdfs:subClassOf ?superType . }

  # Retrieve other properties and values as details (e.g., labels, definitions)
  OPTIONAL { ?stormAttribute ?property ?value . }
}
ORDER BY ?stormAttribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?property ?value
WHERE {
  VALUES ?floodType { 
    kwg-ont:NOAAFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAACoastalFlood 
    kwg-ont:NOAALakeshoreFlood 
  }
  OPTIONAL { ?floodType rdfs:subClassOf* ?superType . }
  OPTIONAL { ?floodType ?property ?value . }
}
ORDER BY ?floodType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}
ORDER BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeHazard ?superType ?property ?value
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeHazard rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeHazard ?property ?value . }
}
ORDER BY ?earthquakeHazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneClass ?hazardProperty ?hazardValue ?damageDetail ?temporalData
WHERE {
  # Identify Hurricane Hazard Class (and its hierarchy)
  kwg-ont:NOAAHurricane rdfs:subClassOf* ?hurricaneClass .

  # Ensure it is related to a geographical place (Hazard -> geo:Feature)
  ?hurricaneClass rdfs:subClassOf* geo:Feature .

  # Retrieve attributes/properties of the hurricane hazard class
  OPTIONAL { ?hurricaneClass ?hazardProperty ?hazardValue }

  # Identify damage impact details (Observable Properties for Impact)
  ?damageDetail rdfs:subClassOf kwg-ont:ImpactObservableProperty .

  # Retrieve temporal data if available for the hurricane or impact observations
  OPTIONAL { ?hurricaneClass sosa:phenomenonTime ?temporalData }
  OPTIONAL { ?hurricaneClass time:hasBeginning ?temporalData }
  OPTIONAL { ?hurricaneClass time:hasEnd ?temporalData }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author WHERE {
  ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department
WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisorName
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisorName .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?department a coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?name }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author rdf:type coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?universityLabel ?cityName
WHERE {
  ?uni a coresr-ont:University .
  OPTIONAL { ?uni rdfs:label ?universityLabel }
  ?uni coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  OPTIONAL { ?city rdfs:label ?cityName }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?type ?typeName
WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?typeName .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?fieldOfStudy ?publication ?title
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?pub ?title WHERE {
  {
    SELECT ?pub (COUNT(DISTINCT ?dept) AS ?cnt) 
    WHERE {
      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:hasContributor ?contributor .
      ?contributor coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?dept .
    }
    GROUP BY ?pub
    HAVING (COUNT(DISTINCT ?dept) > 1)
  }
  FILTER (?cnt > 1)
  ?pub coresr-ont:hasTitle ?title .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?department coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?area ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name ?diabetic ?obese
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasPopulation ?population .
  ?place kwgl-ont:hasNumberOfHouseHolds ?households .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name (
    (SELECT (COUNT(?e) WHERE { ?e rdf:type kwgl-ont:Earthquake }) AS ?total_count)
)
WHERE {
    ?hazard rdf:type kwgl-ont:Earthquake .
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?placeName ?hazardName ?hazardType ?startDate ?endDate ?affectedArea ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasImpacted ?place ;
          kwgl-ont:hasHazardType ?hazardType ;
          kwgl-ont:hasName ?hazardName ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate ?endDate ;
          kwgl-ont:affectedAreaInAcres ?affectedArea ;
          kwgl-ont:numberOfDeaths ?deaths .

  ?place kwgl-ont:hasName ?placeName .

  FILTER (STR(?hazardType) CONTAINS "storm" || STR(?hazardType) = "tornado" || STR(?hazardType) = "hurricane")
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?name ?damage ?count
WHERE {
    ?place a kwgl-ont:Place .
    OPTIONAL { ?place kwgl-ont:hasName ?name }
    FILTER EXISTS {
        { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damage }
        UNION
        { ?place kwgl-ont:numberOfFloodsImpactingPlace ?count }
    }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?property WHERE {
  kwgl-ont:Place ?property ?type .
  FILTER(CONTAINS(STR(?property), "Temperature") || CONTAINS(STR(?property), "Degree"))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?type ?startDate ?endDate ?area ?damageInfra ?damageCrops ?deaths
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?name ?affectedArea ?cropDamage ?infraDamage ?deaths
WHERE {
    ?event a kwgl-ont:HazardEvent .
    OPTIONAL { ?event kwgl-ont:hasName ?name }
    OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
    OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?damageType ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL {
    ?hazard kwgl-ont:damageToCropsInDollars ?damageValue .
    BIND("Damage to Crops" AS ?damageType)
  }
  OPTIONAL {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageValue .
    BIND("Damage to Infrastructure" AS ?damageType)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?placeName ?hurricaneName ?startDate ?endDate ?affectedArea ?cropDamage ?infraDamage ?deaths 
       ?placeHurricaneDollarDamage ?placeNumHurricanes
       ?damage2018 ?damage2019 ?damage2020 ?damage2021 ?damage2022
       ?num2018 ?num2019 ?num2020 ?num2021 ?num2022
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL {
    ?hurricane rdf:type kwgl-ont:Hurricane .
    ?place kwgl-ont:impactedBy ?hurricane .

    ?hurricane kwgl-ont:hasName ?hurricaneName .
    ?hurricane kwgl-ont:hasStartDate ?startDate .
    ?hurricane kwgl-ont:hasEndDate ?endDate .
    ?hurricane kwgl-ont:affectedAreaInAcres ?affectedArea .
    ?hurricane kwgl-ont:damageToCropsInDollars ?cropDamage .
    ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infraDamage .
    ?hurricane kwgl-ont:numberOfDeaths ?deaths .
  }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?placeHurricaneDollarDamage . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?placeNumHurricanes . }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damage2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damage2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damage2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damage2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damage2022 . }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?num2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?num2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?num2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?num2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?num2022 . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?label ?property ?value ?when
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?label }
  OPTIONAL { 
    ?hazard ?property ?value .
    FILTER(?property != rdf:type)
  }
  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    ?temporalEntity time:inXSDDateTime ?when .
  }
}
ORDER BY ?hazard ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?healthEntity ?superType ?property ?value
WHERE {
  { ?healthEntity a kwg-ont:Hospital } UNION
  { ?healthEntity a kwg-ont:PublicHealthDepartment } UNION
  { ?healthEntity a kwg-ont:VulnerabilityObservation }

  OPTIONAL { ?healthEntity rdfs:subClassOf* ?superType . }
  OPTIONAL { ?healthEntity ?property ?value . }
}
ORDER BY ?healthEntity ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute a kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}
ORDER BY ?label

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?label (SELECT (COUNT(*) AS ?totalCount) WHERE { ?x rdf:type kwg-ont:Earthquake }) AS ?count
WHERE {
  ?hazard rdf:type kwg-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:label ?label }
}
ORDER BY ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?property (COUNT(DISTINCT ?prop) AS ?totalAttributes) WHERE {
  ?hazard a kwg-ont:NOAATornado .
  ?hazard ?property ?value .
  { SELECT (COUNT(DISTINCT ?p) AS ?prop) WHERE { ?hazard2 a kwg-ont:NOAATornado . ?hazard2 ?p ?v . } }
} GROUP BY ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stormType ?propName ?propLabel
WHERE {
  # Identify storm-specific hazard classes (NOAA Hazard Events and Storm Tracks)
  {
    ?stormType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  } UNION {
    ?stormType rdfs:subClassOf* kwg-ont:StormTrack .
  }

  # Retrieve associated property labels (attributes) for these classes
  OPTIONAL {
    ?prop rdfs:domain ?stormType .
    ?prop rdfs:label ?propLabel .
  }

  # Ensure we capture the class label as a detail of the hazard type itself
  ?stormType rdfs:label ?stormLabel .
}
ORDER BY ?stormType ?propName

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?floodInstance ?property ?value ?geoPlace
WHERE {
  # Identify flood-specific hazard instances
  { ?floodInstance a kwg-ont:NOAAFlood } UNION
  { ?floodInstance a kwg-ont:NOAACoastalFlood } UNION
  { ?floodInstance a kwg-ont:NOAALakeshoreFlood }

  # Retrieve attributes and details
  OPTIONAL { ?floodInstance ?property ?value . }

  # Capture geographical place relations if available
  OPTIONAL { ?floodInstance kwg-ont:sfWithin ?geoPlace . }
}
ORDER BY ?floodInstance ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute a kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}
ORDER BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?factorLabel ?value
WHERE {
  ?hazardEvent a kwg-ont:Hazard .
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProp .
  ?impactProp rdfs:label ?factorLabel .
  OPTIONAL {
    ?obs sosa:hasResult ?result .
    ?result sosa:hasSimpleResult ?value .
  }
}
ORDER BY ?hazardEvent ?factorLabel

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
