PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub ?title (COUNT(DISTINCT ?dept) AS ?numDepts)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:hasTitle ?title .

  {
    ?pub coresr-ont:hasContributor ?role .
    ?role coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  } UNION {
    ?pub coresr-ont:submittedBy ?authorRole .
    ?authorRole coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }
} GROUP BY ?pub ?title HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author WHERE {
  # Authors must have advisors
  ?author coresr-ont:advisedBy ?advisor .

  # Ensure no field is missing for this author's submissions
  FILTER NOT EXISTS {
    # Identify a field of study that exists in the graph via any publication
    ?anyPub coresr-ont:associatedFieldOfStudy ?field .

    # Check if the current author has NO submission associated with this specific field
    FILTER NOT EXISTS {
      ?author coresr-ont:submits ?pub .
      ?pub coresr-ont:associatedFieldOfStudy ?field .
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?dept (COUNT(?agent) AS ?missingAgentCount)
WHERE {
  ?dept coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?fn .
    ?fn rdf:type coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingAgentCount)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
