SELECT ?hazard ?details ?timeOfHappening
WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL {
    ?hazard rdfs:label ?details .
  }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeOfHappening .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name WHERE {
  ?place rdf:type kwg-ont:Region .
  OPTIONAL {
