PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attributeURI (STR(?attrName) AS ?attributeLabel)
WHERE {
  # Retrieve health-related observable properties and attributes associated with geographical places.
  # Based on the schema, Public Health and Vulnerability observables are defined for Administrative Regions (Places).

  {?observableProp rdfs:subClassOf kwg-ont:PublicHealthObservableProperty} 
  UNION 
  {?observableProp rdfs:subClassOf kwg-ont:VulnerabilityObservableProperty}

  BIND(?observableProp AS ?attributeURI)

  # Attempt to retrieve label for the attribute
  OPTIONAL {
    ?observableProp rdfs:label ?attrName .
  }

  # Ensure the attributes are linked to geographical places via observation structures defined in schema context.
  # The schema specifies PublicHealthObservationCollection links AdministrativeRegion_3 (Place) to observations.
  FILTER EXISTS {
    {?collection sosa:hasFeatureOfInterest kwg-ont:AdministrativeRegion_3 . 
     ?collection sosa:observedProperty/kwg-ont:subClassOf* ?observableProp}

    UNION

    {?observation sosa:hasFeatureOfInterest kwg-ont:AdministrativeRegion_3 . 
     ?observation sosa:observedProperty ?observableProp}

    UNION

    # Also check for direct observations on generic Features acting as places
    {?observation sosa:hasFeatureOfInterest ?place . 
     ?place a geo:Feature .
     ?observation sosa:observedProperty/kwg-ont:subClassOf* ?observableProp}
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard (SELECT (COUNT(*) AS ?count) WHERE { ?any a kwg-ont:Earthquake . } )
WHERE {
  ?hazard a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geosparql: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attribute (COUNT(?total) AS ?count_total) WHERE {
  VALUES ?hazardType { kwg-ont:NOAAHazardEvent kwg-ont:MagnitudeObservableProperty }
  # Find Observable Properties relevant to Tornado/Hazard Magnitude
  OPTIONAL { 
    ?attr rdfs:subClassOf|a kwg-ont:MagnitudeObservableProperty .
    ?attr a sosa:ObservableProperty .
  }
  UNION 
  {
    SELECT (COUNT(?anyAttr) AS ?total) WHERE {
       ?anyAttr rdfs:subClassOf|a kwg-ont:MagnitudeObservableProperty ;
                a sosa:ObservableProperty .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardClass ?hazardName ?attributeClass ?attributeName WHERE {
  # Select storm-specific hazards (Subclasses of NOAAHazardEvent)
  ?hazardClass a kwg-ont:NOAAHazardEvent .

  # Retrieve hazard details (names/labels)
  OPTIONAL { 
    ?hazardClass rdfs:label ?hazardName .
  }

  # Retrieve attributes (Observable Properties) linked to this hazard via observations
  ?observation sosa:hasFeatureOfInterest ?hazardClass ;
               sosa:observedProperty ?attributeClass .

  # Retrieve attribute details (names/labels)
  OPTIONAL { 
    ?attributeClass rdfs:label ?attributeName .
  }

  # Ensure they are related to geographical places (Geo Feature definition)
  ?hazardClass a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?label ?geometryId ?geometryType ?spatialRelation
WHERE {
  VALUES (?type) { (kwg-ont:NOAAFlood) (kwg-ont:NOAAFlashFlood) (kwg-ont:NOAACoastalFlood) (kwg-ont:NOAALakeshoreFlood) }

  ?hazard a ?type .

  OPTIONAL { ?hazard rdfs:label ?label }

  ?hazard kwg-ont:hasGeometry ?geometryUri .
  ?geometryId <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> ?geometryType .

  OPTIONAL { 
    ?hazard kwg-ont:spatialRelation ?spatialRelation .
    FILTER(!isIRI(?spatialRelation) || STRSTARTS(STR(?spatialRelation), "http"))
  }
}
ORDER BY ?label

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?attribute ?name
WHERE {
  VALUES ?type { 
    kwg-ont:ClimateObservableProperty 
    sosa:ObservableProperty 
  }

  {?prop rdf:type ?class . FILTER(?class = kwg-ont:ClimateObservableProperty)}
  UNION
  {?prop rdfs:subClassOf kwg-ont:ClimateObservableProperty}
  UNION
  {?prop a kwg-ont:ClimateObservableProperty}

  OPTIONAL { ?prop rdfs:label ?name }
  FILTER(BOUND(?name))

  # Ensure attributes are related to climate features which are geographical places
  FILTER NOT EXISTS { 
    ?obs sosa:observedProperty ?prop . 
    FILTER(BOUND(?obs))
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?earthquake ?hazardType ?geometry ?temporalScope
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  # Retrieving the hazard type (known from schema hierarchy as Hazard)
  BIND("Hazard" AS ?hazardType) 

  OPTIONAL {
    ?earthquake kwg-ont:hasGeometry ?geometry .
  }
  OPTIONAL {
    ?earthquake geo:hasDefaultGeometry ?geoDef .
  }
  OPTIONAL {
    ?earthquake kwg-ont:hasTemporalScope ?temporalScope .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?damageDetail WHERE {
  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?damageDetail .
  ?hazard rdf:type kwg-ont:Hazard .
  ?observation sosa:hasFeatureOfInterest ?hazard .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneURI ?attributeType ?impactDetail ?temporalData WHERE {
  # Identify Hurricane Hazard Event instances which are subclasses of NOAAHazardEvent
  ?hurricane a kwg-ont:NOAAHurricane .

  # Ensure the hazard is related to a geographical place (has geometry/feature status)
  ?hurricane geo:hasDefaultGeometry ?geometry ;
             geo:hasGeometry ?geoGeom .

  # Link to Observation Collections that are associated with this Hurricane Event
  ?collection sosa:phenomenonTime ?temporalData ;
              sosa:hasFeatureOfInterest ?hurricane ;
              sosa:observedProperty ?attributeType .

  # Identify if the attribute is a specific damage impact detail (ImpactObservableProperty subclass)
  OPTIONAL {
      FILTER(STRSTARTS(?attributeType, "http://example.org/kwg#") && 
             EXISTS {?property rdfs:subClassOf* kwg-ont:ImpactObservableProperty . ?collection sosa:observedProperty ?property})
      BIND("Damage_Impact" AS ?impactDetail)
  }

  # General hazard attribute identification for non-damage properties (e.g. Magnitude/Wind)
  FILTER NOT EXISTS {
       ?prop rdfs:subClassOf* kwg-ont:ImpactObservableProperty . 
       FILTER(STRSTARTS(?attributeType, STR(?prop)))
       BIND("Damage_Impact" AS ?impactDetail)
     }

}

