}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?name 
       ?floodCount ?floodDamage 
       ?floodCount2018 ?floodDamage2018 
       ?floodCount2019 ?floodDamage2019 
       ?floodCount2020 ?floodDamage2020 
       ?floodCount2021 ?floodDamage2021 
       ?floodCount2022 ?floodDamage2022
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }

  # General Flood Attributes
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?floodCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage }

  # Yearly Details (2018)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?floodCount2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?floodDamage2018 }

  # Yearly Details (2019)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?floodCount2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?floodDamage2019 }

  # Yearly Details (2020)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?floodCount2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?floodDamage2020 }

  # Yearly Details (2021)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?floodCount2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?floodDamage2021 }

  # Yearly Details (2022)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?floodCount2022 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?floodDamage2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?area ?damage
WHERE {
    ?hazard rdf:type kwgl-ont:Earthquake .
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }
    OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
    OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
    OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?placeName ?startDate ?endDate 
       ?damageToCropsInDollars ?damageToInfrastructureInDollars 
       ?tornadoDamageGeneral ?tornadoDamage2018 ?tornadoDamage2019 ?tornadoDamage2020 ?tornadoDamage2021 ?tornadoDamage2022
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType kwglr:tornado .
  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?hazardEvent kwgl-ont:hasStartDate ?startDate .
  ?hazardEvent kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamageGeneral }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?tornadoDamage2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?tornadoDamage2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?tornadoDamage2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?tornadoDamage2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?tornadoDamage2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazard ?place ?damageInfra ?damageCrops ?area ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  # Identify storm-specific hazards (Classes or Types)
  {
    ?hazard a kwgl-ont:Hurricane .
  } UNION {
    ?hazard a kwgl-ont:Tornado .
  } UNION {
    ?hazard kwgl-ont:hasHazardType kwglr:hurricane .
  } UNION {
    ?hazard kwgl-ont:hasHazardType kwglr:tornado .
  } UNION {
    ?hazard kwgl-ont:hasHazardType kwglr:stormSurgeTide .
  }

  # Related to a geographical place
  ?hazard kwgl-ont:hasImpacted ?place .

  # Temporal extent (must have start and end dates)
  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .

  # Damage details available on the HazardEvent
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
}

