PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent
  ?name
  ?startDate
  ?endDate
  ?hazardType
  ?affectedArea
  ?cropsDamage
  ?infraDamage
  ?deaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard (SELECT COUNT(DISTINCT ?item) WHERE { 
    { ?item rdf:type owl:Class . } UNION { ?item rdf:type kwgl-ont:HazardType . }
    FILTER(CONTAINS(LCASE(STR(?item)), "earthquake"))
}) AS ?totalCount
WHERE { 
    SELECT DISTINCT ?hazard WHERE {
        { ?hazard rdf:type owl:Class . } UNION { ?hazard rdf:type kwgl-ont:HazardType . }
        FILTER(CONTAINS(LCASE(STR(?hazard)), "earthquake"))
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?prop ?label (SELECT (COUNT(DISTINCT ?p) AS ?total) WHERE { ?p rdf:type owl:DatatypeProperty . FILTER(CONTAINS(LCASE(STR(?p)), "tornado") && CONTAINS(LCASE(STR(?p)), "place")) }) AS ?count
WHERE {
  ?prop rdf:type owl:DatatypeProperty .
  OPTIONAL { ?prop rdfs:label ?label }
  FILTER (CONTAINS(LCASE(STR(?prop)), "tornado") && CONTAINS(LCASE(STR(?prop)), "place"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel ?domain
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:domain ?domain . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?hazardName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?hazardTypeLabel
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:earthquake .

  OPTIONAL { 
    ?hazard kwgl-ont:hasName ?hazardName 
    . FILTER (BOUND(?hazardName))
  }

  OPTIONAL { 
    ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres 
  }

  OPTIONAL { 
    ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars 
  }

  OPTIONAL { 
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars 
  }

  BIND(kwglr:earthquake AS ?hazardType)
  OPTIONAL { 
    ?hazardType rdfs:label ?hazardTypeLabel .
  }
}
ORDER BY ?hazardName

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?areaInAcres ?cropDamageDollars ?infraDamageDollars ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamageDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamageDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}
ORDER BY ?event ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageDetail ?label ?range
WHERE {
  ?damageDetail rdf:type owl:DatatypeProperty .

  OPTIONAL { ?damageDetail rdfs:domain kwgl-ont:HazardEvent . }
  OPTIONAL { ?damageDetail rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?damageDetail rdfs:range ?range . }
  OPTIONAL { ?damageDetail rdfs:label ?label . }

  FILTER (CONTAINS(LCASE(STR(?damageDetail)), "damage") || 
          CONTAINS(LCASE(STR(?label)), "damage"))
}
ORDER BY ?damageDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?place ?cropDamage ?infraDamage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:tornado .
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?event ?eventName ?hazardTypeLabel ?startDate ?endDate ?placeName ?damageProperty ?damageValue
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  # Hazard Event and Place Relationship
  ?event kwgl-ont:hasImpacted ?place .

  # Storm-Specific Hazard Filter (checking URI for storm or hurricane keywords)
  ?event kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel }
  FILTER (CONTAINS(LCASE(STR(?hazardType)), "storm") || CONTAINS(LCASE(STR(?hazardType)), "hurricane"))

  # Event Metadata
  OPTIONAL { ?event kwgl-ont:hasName ?eventName }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  # Place Metadata
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Damage Details (Retrieving available damage properties on HazardEvent)
  OPTIONAL {
    ?event kwgl-ont:damageToCropsInDollars ?damageValue1 .
    BIND(kwgl-ont:damageToCropsInDollars AS ?damageProperty)
    BIND(?damageValue1 AS ?damageValue)
  }
  OPTIONAL {
    ?event kwgl-ont:damageToInfrastructureInDollars ?damageValue2 .
    BIND(kwgl-ont:damageToInfrastructureInDollars AS ?damageProperty)
    BIND(?damageValue2 AS ?damageValue)
  }
}
ORDER BY ?startDate ?endDate ?hazardTypeLabel ?placeName

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

