SELECT ?publication
WHERE {
  { 
    # Publications with Authors (direct submission link)
    ?publication coresr-ont:submittedBy ?role .
  } UNION {
    # Publications with Contributors (reverse contribution link)
    ?role coresr-ont:contributedTo ?publication .
  }

  # Link Role to Agent
  ?role coresr-ont:isPerformedBy ?agent .

  # Link Agent to Department
  ?agent coresr-ont:associatedWith ?department .
