SELECT ?hazard ?name ?time WHERE {
  ?hazard a kwg-ont:Hazard .
  ?hazard kwg-ont:hasTemporalScope ?time .
  OPTIONAL { ?hazard rdfs:label ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?property ?label
WHERE {
  VALUES ?healthClass { kwg-ont:PublicHealthObservableProperty kwg-ont:VulnerabilityObservableProperty }
  ?property a ?healthClass .
  OPTIONAL { ?property rdfs:label ?label }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute ?place
WHERE {
    ?collection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
                sosa:hasFeatureOfInterest ?place .
    ?collection sosa:hasMember ?observation .
    ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
                 sosa:observedProperty ?attribute .
    ?attribute rdfs:subClassOf kwg-ont:CensusObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake (COUNT(?earthquake) AS ?count) WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?attribute (SELECT (COUNT(*) AS ?total_count) WHERE { ?x rdfs:subClassOf kwg-ont:MagnitudeObservableProperty } )
WHERE { 
  ?attribute rdfs:subClassOf kwg-ont:MagnitudeObservableProperty .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?attribute ?label WHERE {
  {
    ?attribute a kwg-ont:StormTrackObservableProperty .
  } UNION {
    ?attribute a kwg-ont:StormTrackletObservableProperty .
  }
  OPTIONAL { ?attribute rdfs:label ?label }
  # Ensure the attributes are related to spatial features (geographical places) via parent class geometry
  FILTER EXISTS {
    ?hazard a kwg-ont:StormTrack ; geo:hasGeometry ?geometry .
  } || FILTER EXISTS {
    ?hazard a kwg-ont:StormTracklet ; geo:hasDefaultGeometry ?geometry .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?property ?value WHERE {
  {
    ?hazard a kwg-ont:NOAAFlood .
  } UNION {
    ?hazard a kwg-ont:NOAACoastalFlood .
  } UNION {
    ?hazard a kwg-ont:NOAAFlashFlood .
  } UNION {
    ?hazard a kwg-ont:NOAALakeshoreFlood .
  }

  OPTIONAL {
    ?hazard ?property ?value .
    FILTER (?property != rdf:type)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attr WHERE {
  ?observation a kwg-ont:ClimateObservation ;
               sosa:observedProperty ?attr .
  ?observation sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?type ?temporalScope ?geometry WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  ?earthquake rdf:type ?type .
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope }
  OPTIONAL { ?earthquake geo:hasGeometry ?geometry }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hurricane ?geometry ?spatialRelation ?impactProperty ?impactValue ?temporalData
WHERE {
  # Identify Hurricane instances
  ?hurricane a kwg-ont:NOAAHurricane .

  # Retrieve hurricane attributes related to geographical place (Geometry or Spatial Relation)
  OPTIONAL { ?hurricane geo:hasGeometry ?geometry }
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?spatialRelation }

  # Retrieve damage impact details via ImpactObservationCollection linked to the hazard
  ?collection a kwg-ont:ImpactObservationCollection .
  ?collection sosa:hasFeatureOfInterest ?hurricane .

  # Temporal data if available
  OPTIONAL { ?collection sosa:phenomenonTime ?temporalData }

  # Impact details (Observable Property and Result)
  ?collection sosa:hasMember ?observation .
  OPTIONAL { ?observation sosa:observedProperty ?impactProperty }
  OPTIONAL { ?observation sosa:hasSimpleResult ?impactValue }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?startDate ?endDate ?typeURI ?typeName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?typeURI .
    OPTIONAL { ?typeURI rdfs:label ?typeName }
  }

  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?propertyLabel ?value
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  VALUES (?property) {
    (kwgl-ont:percentDiabetic)
    (kwgl-ont:percentObese)
    (kwgl-ont:percentBelowPovertyLine)
  }

  ?place ?property ?value .
  OPTIONAL { ?property rdfs:label ?propertyLabel }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attributeLabel ?value
WHERE {
  {
    ?place a kwgl-ont:Place ;
           kwgl-ont:hasPopulation ?value .
    BIND("population" AS ?attributeLabel)
  } UNION {
    ?place a kwgl-ont:Place ;
           kwgl-ont:hasNumberOfHouseHolds ?value .
    BIND("household units" AS ?attributeLabel)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard (COUNT(?hazard) AS ?count) WHERE {
  ?hazard a kwgl-ont:HazardType .
  FILTER(CONTAINS(STR(?hazard), "earthquake"))
} GROUP BY ?hazard

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?label (COUNT(?prop) AS ?total_count)
WHERE {
    ?prop a owl:DatatypeProperty ;
          rdfs:domain kwgl-ont:Place ;
          rdfs:label ?label .
    FILTER(CONTAINS(LCASE(str(?label)), "tornado"))
}
GROUP BY ?label

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?placeName ?attributeLabel ?value WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  UNION {
    # Storm-specific attributes directly defined on Places (e.g., impact statistics)
    ?place ?prop ?value .
    FILTER(REGEX(STR(?prop), "storm", "i")) .
    OPTIONAL { ?prop rdfs:label ?attributeLabel }
  }

  UNION {
    # Storm-related Hazard Events impacting Places and their details
    ?place kwgl-ont:impactedBy ?hazard .
    ?hazard kwgl-ont:hasHazardType ?type .
    FILTER(REGEX(STR(?type), "storm|Hurricane", "i")) .

    # Retrieve attributes of the Storm Hazard Event (e.g., start/end date, damage)
    ?hazard ?eventProp ?value .
    OPTIONAL { ?eventProp rdfs:label ?attributeLabel }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardUri ?hazardName ?affectedArea ?cropDamage ?infraDamage ?deaths ?startDate ?endDate ?placeName ?impactedByPlace
WHERE {
  # Find Hazard Events of type Flood linked to Places
  ?haz rdf:type kwgl-ont:HazardEvent ;
       kwgl-ont:hasHazardType kwglr:flood .

  OPTIONAL {
    ?haz kwgl-ont:hasName ?hazardName ;
         kwgl-ont:affectedAreaInAcres ?affectedArea ;
         kwgl-ont:damageToCropsInDollars ?cropDamage ;
         kwgl-ont:damageToInfrastructureInDollars ?infraDamage ;
         kwgl-ont:numberOfDeaths ?deaths ;
         kwgl-ont:hasStartDate ?startDate ;
         kwgl-ont:hasEndDate ?endDate .
    ?haz kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?place kwgl-ont:hasName ?impactedByPlace }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?type ?startDate ?endDate
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?affectedArea ?cropDamage ?infraDamage
WHERE {
    ?hazard a kwgl-ont:HazardEvent .
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }
    OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
    OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?placeName ?startDate ?endDate ?cropDamage ?infraDamage ?areaInAcres ?deaths
WHERE {
  ?hazardEvent a kwgl-ont:Tornado ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }

  OPTIONAL { ?place rdfs:label ?placeName }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?placeName ?startDate ?endDate ?damageType ?damageValue
WHERE {
  # Identify storm-specific hazards (Hurricane or Tornado classes)
  { ?hazard rdf:type kwgl-ont:Hurricane } UNION
  { ?hazard rdf:type kwgl-ont:Tornado }

  # Ensure the event has a defined temporal extent
  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .

  # Link to affected geographical place and get its name
  ?hazard kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  # Retrieve available damage details associated with the hazard event
  {
    ?hazard kwgl-ont:damageToCropsInDollars ?damageValue .
    BIND("Damage to Crops (USD)" AS ?damageType)
  } UNION {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageValue .
    BIND("Damage to Infrastructure (USD)" AS ?damageType)
  } UNION {
    ?hazard kwgl-ont:affectedAreaInAcres ?damageValue .
    BIND("Affected Area (acres)" AS ?damageType)
  } UNION {
    ?hazard kwgl-ont:numberOfDeaths ?damageValue .
    BIND("Number of Deaths" AS ?damageType)
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author .
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?fieldOfStudy ?title
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  ?publication coresr-ont:hasTitle ?title .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  {
    ?publication coresr-ont:submittedBy ?person .
    ?person coresr-ont:associatedWith ?department .
