HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?time WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasName ?name }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?name WHERE {
  VALUES ?class { 
    kwg-ont:AdministrativeRegion 
    kwg-ont:FederalJudicalDistrict 
    kwg-ont:NWZone 
    kwg-ont:NielsenMarketZone 
    kwg-ont:USCensusMSA 
    kwg-ont:USClimateDivision 
    kwg-ont:ZipCodeArea 
  }
  ?place a ?class .
  OPTIONAL { ?place kwg-ont:hasName ?name }
  OPTIONAL { ?place kwg-ont:climateDivisionName ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?healthConcern WHERE {
  ?observation a sosa:Observation ;
               sosa:observedProperty ?healthConcern .
  ?observation sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
  FILTER(?healthConcern IN (kwg-ont:PublicHealthObservableProperty, kwg-ont:VulnerabilityObservableProperty, kwg-ont:ImpactObservableProperty))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attributeURI ?attributeLabel WHERE {
  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:observedProperty ?attributeURI .
  ?attributeURI a kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attributeURI rdfs:label ?attributeLabel }

  # Ensure association with geographical places (Features) via direct link or collection
  {
    ?observation sosa:hasFeatureOfInterest ?place .
    ?place a geo:Feature .
  }
  UNION
  {
    ?collection sosa:hasMember ?observation .
    ?collection sosa:hasFeatureOfInterest ?place .
    ?place a geo:Feature .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?attribute (COUNT(?attribute) AS ?total_count) WHERE {
  ?attr a kwg-ont:MagnitudeObservableProperty .
  OPTIONAL {
    ?collection a kwg-ont:MagnitudeObservationCollection ;
                sosa:observedProperty ?attr ;
                sosa:hasFeatureOfInterest ?hazardEvent .
    ?hazardEvent a kwg-ont:NOAAHazardEvent .
  }
} GROUP BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?propName ?propType ?hazardClass
WHERE {
  # Find Observable Properties (Attributes)
  ?prop a sosa:ObservableProperty .

  # Link to Observations and Features of Interest
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?prop .

  # Filter for Storm-specific Hazard Classes (StormTrack, StormTracklet, NOAAHazardEvent)
  {
    ?hazard a kwg-ont:StormTrack .
  } UNION {
    ?hazard a kwg-ont:StormTracklet .
  } UNION {
    ?hazard a kwg-ont:NOAAHazardEvent .
  }

  # Ensure Hazard is related to Geographical Places (has geometry/feature)
  ?hazard geo:Feature .

  # Retrieve Property Details
  OPTIONAL { ?prop rdfs:label ?propName }
  OPTIONAL { ?prop a ?propType }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attribute ?hazardType WHERE {
  VALUES ?floodClass { kwg-ont:NOAAFlood kwg-ont:NOAACoastalFlood kwg-ont:NOAALakeshoreFlood }

  # Find the collection linking hazards and observations
  ?collection a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?hazard ;
              sosa:hasMember ?observation .

  # Filter for flood-specific hazard types
  { ?hazard a kwg-ont:NOAAFlood } UNION 
  { ?hazard a kwg-ont:NOAACoastalFlood } UNION 
  { ?hazard a kwg-ont:NOAALakeshoreFlood } .

  # Retrieve the observed property (attribute) from the observation
  ?observation sosa:observedProperty ?attribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attribute WHERE {
  ?observation a kwg-ont:ClimateObservation ;
               sosa:observedProperty ?attribute .
  ?observation sosa:hasFeatureOfInterest ?place .
  FILTER(?place IN (kwg-ont:USClimateDivision, kwg-ont:S2Cell, kwg-ont:AdministrativeRegion)) 
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

        SELECT ?hazard ?type ?details
        WHERE {
          ?hazard a kwg-ont:Earthquake .
          ?hazard rdf:type ?type .
          OPTIONAL { ?hazard rdfs:label ?details }
        }

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?hazardType ?geometry ?spatialRelation ?damageProperty ?temporalData
WHERE {
  # Identify Hurricane Hazard Events (specific subclasses of NOAAHazardEvent)
  {
    ?hurricane a kwg-ont:NOAAHurricane .
    BIND("NOAAHurricane" AS ?hazardType)
  } UNION {
    ?hurricane a kwg-ont:NOAAMarineHurricaneTyphoon .
    BIND("NOAAMarineHurricaneTyphoon" AS ?hazardType)
  }

  # Retrieve Geographical Place / Geometry information related to the hazard
  OPTIONAL { ?hurricane geo:hasDefaultGeometry ?geometry . }
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?spatialRelation . }

  # Link to Damage Impact Details via Observation Collections
  ?collection a kwg-ont:ImpactObservationCollection ;
              sosa:hasFeatureOfInterest ?hurricane ;
              sosa:phenomenonTime ?temporalData .

  OPTIONAL {
    ?collection sosa:hasMember ?impactObs .
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?damageProperty .
  }
}

