PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?university ?state ?pubCount
WHERE {
  # Subquery 1: Calculate publication count per university and state
  {
    SELECT ?university ?state (COUNT(?publication) AS ?pubCount)
    WHERE {
      ?university a coresr-ont:University .
      ?university coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      ?university coresr-ont:hasPart ?publication .
      ?publication a coresr-ont:Publication .
    }
    GROUP BY ?university ?state
  }

  # Filter to keep only universities with the maximum publication count for their state
  FILTER( NOT EXISTS {
    SELECT ?otherState (MAX(?c) AS ?maxCount)
    WHERE {
      BIND(?state AS ?otherState)

      ?u a coresr-ont:University .
      ?u coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?otherState .
      ?u coresr-ont:hasPart ?p .
      ?p a coresr-ont:Publication .

      GROUP BY ?u (COUNT(?p) AS ?c)
    }
  })
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title }

  {
    ?publication coresr-ont:hasContributor ?role .
    ?role coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }
  UNION
  {
    ?publication coresr-ont:submittedBy ?role .
    ?role coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }

  GROUP BY ?publication ?title
  HAVING (COUNT(DISTINCT ?dept) > 1)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  # Author must have an advisor
  ?author coresr-ont:advisedBy ?advisor .

  # Ensure author has submitted at least one publication (optimization)
  ?author coresr-ont:submits ?pub .

  # Division Logic: Filter out authors who do not cover all fields of study
  FILTER NOT EXISTS {
    ?field a coresr-ont:FieldOfStudy .
    FILTER NOT EXISTS {
      ?author coresr-ont:submits ?pub2 .
      ?pub2 coresr-ont:associatedFieldOfStudy ?field .
    }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
