PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?property ?value ?place
WHERE {
  # Identify storm-specific hazard classes and their instances (subclasses of NOAAHazardEvent or StormTrack)
  ?hazard rdf:type kwg-ont:NOAAHazardEvent .
  # Filter for hazards related to geographical places (ensure they are Features with spatial relations)
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?geometry } .

  # Retrieve all attributes/details associated with the hazard
  OPTIONAL { 
    ?hazard ?property ?value .
  }

  # If specific place relation is required to filter/return (e.g. sfWithin, sfContains)
  OPTIONAL { 
    ?hazard kwg-ont:sfWithin ?place .
    ?place rdf:type kwg-ont:AdministrativeRegion .
  }
}
ORDER BY ?hazard ?property

Answer: PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?property ?value ?place
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazard rdf:type ?type }
  FILTER (ISIRI(?hazard) || ?type IN ("NOAAHazardEvent", "StormTrack"))
  OPTIONAL { 
    ?hazard geo:hasDefaultGeometry ?geometry .
  }
  OPTIONAL {
    ?hazard ?property ?value .
  }
  OPTIONAL {
    ?hazard kwg-ont:sfWithin ?place .
    ?place rdf:type kwg-ont:AdministrativeRegion .
  }
}
ORDER BY ?hazard ?property ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?label ?superType ?property ?value
WHERE {
  # Identify flood-specific hazard classes (subclasses of NOAA Hazard Event with "Flood" in label)
  ?floodType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  ?floodType rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "flood"))

  # Retrieve hierarchy (immediate or super classes) for type details
  OPTIONAL { 
    ?floodType rdfs:subClassOf* ?superType .
  }

  # Retrieve available attributes/properties and their values associated with the class
  OPTIONAL { 
    ?floodType ?property ?value .
  }
}
ORDER BY ?floodType ?label ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType }
  OPTIONAL { ?earthquakeType ?property ?value }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?tornadoURI ?damageDetailType ?timeExtent ?geographicalPlaceURI
WHERE {
  # Identify Tornado Hazards in the Knowledge Graph
  ?tornadoURI a kwg-ont:NOAATornado .

  # Link to Observations containing damage details (Impact Observations)
  ?observation sosa:hasFeatureOfInterest ?tornadoURI ;
               a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?damageDetailType .

  # Retrieve temporal extent associated with the observation (if available)
  OPTIONAL { 
    ?observation sosa:resultTime ?timeExtent .
  }

  # Retrieve geographical place relation for the hazard (if linked via spatial containment)
  OPTIONAL { 
    ?tornadoURI kwg-ont:sfWithin ?geographicalPlaceURI .
  }
}
ORDER BY ?tornadoURI ?damageDetailType ?timeExtent ?geographicalPlaceURI

