  FILTER (?attribute IN (kwgl-ont:hasPopulation, kwgl-ont:hasNumberOfHouseHolds, kwgl-ont:percentBelowPovertyLine, kwgl-ont:percentDiabetic, kwgl-ont:percentObese))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?name (subQueryCount AS ?total_count) WHERE {
  SELECT ?hazard ?name (SELECT (COUNT(*) AS ?countVal) 
                           WHERE {
                             { ?x rdf:type kwgl-ont:HazardEvent } UNION { ?x rdf:type kwgl-ont:Earthquake } .
                             OPTIONAL { ?x kwgl-ont:hasHazardType kwglr:earthquake }
                             FILTER(BOUND(?x))
                           }) AS subQueryCount
  WHERE {
    { ?hazard rdf:type kwgl-ont:HazardEvent } UNION { ?hazard rdf:type kwgl-ont:Earthquake } .
    OPTIONAL { ?hazard kwgl-ont:hasHazardType kwglr:earthquake }
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place (STR(?name) AS ?name) 
       ?numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace_2018 ?numberOfFloodsImpactingPlace_2019 ?numberOfFloodsImpactingPlace_2020 ?numberOfFloodsImpactingPlace_2021 ?numberOfFloodsImpactingPlace_2022
       ?dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace_2018 ?dollarDamageOfFloodsImpactingPlace_2019 ?dollarDamageOfFloodsImpactingPlace_2020 ?dollarDamageOfFloodsImpactingPlace_2021 ?dollarDamageOfFloodsImpactingPlace_2022
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?numberOfFloodsImpactingPlace_2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?numberOfFloodsImpactingPlace_2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?numberOfFloodsImpactingPlace_2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?numberOfFloodsImpactingPlace_2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?numberOfFloodsImpactingPlace_2022 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?dollarDamageOfFloodsImpactingPlace_2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace_2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?dollarDamageOfFloodsImpactingPlace_2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace_2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?dollarDamageOfFloodsImpactingPlace_2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?earthquake ?name ?hazardType ?startDate ?endDate ?numberOfDeaths
WHERE {
    ?earthquake a kwgl-ont:Earthquake .
    ?earthquake kwgl-ont:hasName ?name .
    OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType }
    OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?name ?startDate ?endDate ?deaths ?cropsDamage ?infraDamage ?area_affected ?kwgEntity
WHERE {
    ?hazardEvent a kwgl-ont:HazardEvent .
    OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
    OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropsDamage }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
    OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area_affected }
    OPTIONAL { ?hazardEvent kwgl-ont:hasKWGEntity ?kwgEntity }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?entityName ?hazardName ?damageProperty ?damageValue WHERE {
  {
    # Entities impacted by hazards (Places) with general damage details
    ?entity a kwgl-ont:Place ;
            kwgl-ont:impactedBy ?hazard .

    OPTIONAL { ?entity kwgl-ont:hasName ?entityName }
    OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageValue } BIND("dollarDamageOfFiresImpactingPlace" AS ?damageProperty)
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageValue } BIND("dollarDamageOfFloodsImpactingPlace" AS ?damageProperty)
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageValue } BIND("dollarDamageOfHurricanesImpactingPlace" AS ?damageProperty)
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageValue } BIND("dollarDamageOfLandslidesImpactingPlace" AS ?damageProperty)
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageValue } BIND("dollarDamageOfStormSurgesImpactingPlace" AS ?damageProperty)
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageValue } BIND("dollarDamageOfTornadoesImpactingPlace" AS ?damageProperty)

  } UNION 
  {
    # HazardEvents with their specific damage details
    ?hazard a kwgl-ont:HazardEvent .
    ?hazard kwgl-ont:hasName ?entityName ;
            kwgl-ont:numberOfDeaths ?damageValue . BIND("numberOfDeaths" AS ?damageProperty)
  } UNION 
  {
    # HazardEvents with infrastructure/crop damage details
    ?hazard a kwgl-ont:HazardEvent .
    OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageValue } BIND("damageToCropsInDollars" AS ?damageProperty)
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageValue } BIND("damageToInfrastructureInDollars" AS ?damageProperty)
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place 
       (COALESCE(?dollarDamageOfHurricanesImpactingPlace, ?dollarDamageOfHurricanesImpactingPlace2018, ?dollarDamageOfHurricanesImpactingPlace2019, ?dollarDamageOfHurricanesImpactingPlace2020, ?dollarDamageOfHurricanesImpactingPlace2021, ?dollarDamageOfHurricanesImpactingPlace2022) AS ?hurricaneDollarDamage)
       (COALESCE(?numberOfHurricanesImpactingPlace, ?numberOfHurricanesImpactingPlace2018, ?numberOfHurricanesImpactingPlace2019, ?numberOfHurricanesImpactingPlace2020, ?numberOfHurricanesImpactingPlace2021, ?numberOfHurricanesImpactingPlace2022) AS ?hurricaneCount)
WHERE {
    ?place a kwgl-ont:Place .

    # Retrieve hurricane-specific damage attributes related to geographical place
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollarDamageOfHurricanesImpactingPlace2018 }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamageOfHurricanesImpactingPlace2019 }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollarDamageOfHurricanesImpactingPlace2020 }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollarDamageOfHurricanesImpactingPlace2021 }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollarDamageOfHurricanesImpactingPlace2022 }

    # Retrieve hurricane-specific count attributes related to geographical place (temporal data via property suffixes)
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?numberOfHurricanesImpactingPlace2018 }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?numberOfHurricanesImpactingPlace2019 }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?numberOfHurricanesImpactingPlace2020 }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?numberOfHurricanesImpactingPlace2021 }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?numberOfHurricanesImpactingPlace2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?cropDamage ?infraDamage WHERE {
  ?hazard a kwgl-ont:Tornado .
  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?hazard ?name ?time WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard rdfs:label ?name .
  }
  OPTIONAL {
    ?hazard skos:prefLabel ?name .
  }
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
    OPTIONAL {
      ?temporalEntity time:inXSDDateTime ?time .
    }
    OPTIONAL {
      ?temporalEntity time:hasBeginning ?start .
      ?start time:inXSDDateTime ?time .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?name WHERE {
  {
    ?place a geo:Feature .
    ?place rdfs:label ?name .
  } UNION {
    ?place a kwg-ont:Region .
    ?place rdfs:label ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?property ?label
WHERE {
  {
    ?property a kwg-ont:PublicHealthObservableProperty .
  } UNION {
    ?property a kwg-ont:VulnerabilityObservableProperty .
  }
  ?property rdfs:label ?label .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard (SELECT (COUNT(?x) WHERE { ?x a kwg-ont:Earthquake }) AS ?total_count) WHERE {
  ?hazard a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?prop ?label ?total_count
WHERE {
  {
    SELECT DISTINCT ?prop ?label
    WHERE {
      ?collection a kwg-ont:TornadoMagnitudeObservationCollection .
      ?collection sosa:hasMember ?observation .
      ?observation sosa:observedProperty ?prop .
      ?prop rdfs:label ?label .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?p) AS ?total_count)
    WHERE {
       ?collection a kwg-ont:TornadoMagnitudeObservationCollection .
       ?collection sosa:hasMember ?observation .
       ?observation sosa:observedProperty ?p .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?hazardLabel ?hazardID ?placeType ?placeName WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent .

  # Retrieve hazard details (labels, IDs, URLs)
  OPTIONAL { ?hazard rdfs:label ?hazardLabel }
  OPTIONAL { ?hazard skos:prefLabel ?hazardLabel }
  OPTIONAL { ?hazard kwg-ont:noaaDisasterID ?hazardID }
  OPTIONAL { ?hazard kwg-ont:detailsURL ?hazardURL }

  # Retrieve related geographical places (Administrative Regions or S2 Cells) via spatial relations
  {
    ?hazard kwg-ont:spatialRelation ?place .
    FILTER(?place != ?hazard)
  }
  UNION
  {
    ?hazard kwg-ont:sfWithin ?place .
  }

  # Identify place type and name
  OPTIONAL { 
    ?place a kwg-ont:AdministrativeRegion_3 ; rdfs:label ?placeName .
    BIND("Administrative Region" AS ?placeType)
  }
  UNION
  {
    ?place a kwg-ont:S2Cell ; rdfs:label ?placeName .
    BIND("S2 Cell" AS ?placeType)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?label ?url ?geometry WHERE {
  VALUES ?floodClass {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
  }

  ?hazard a ?floodClass .

  OPTIONAL { ?hazard rdfs:label ?label . }
  OPTIONAL { ?hazard skos:prefLabel ?label . }
  OPTIONAL { ?hazard kwg-ont:detailsURL ?url . }
  OPTIONAL { 
    ?hazard geo:hasGeometry ?geometry .
    ?geometry geo:asWKT ?wkt .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX terms: <http://purl.org/dc/terms/>

SELECT ?hazard ?type ?name ?description WHERE {
  ?hazard a kwg-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:label ?name }
  OPTIONAL { ?hazard skos:prefLabel ?name }
  OPTIONAL { ?hazard terms:description ?description }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?event ?eventName ?observation ?property ?propertyName
WHERE {
  ?event a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?event rdfs:label ?eventName }

  ?observation sosa:hasFeatureOfInterest ?event ;
             sosa:observedProperty ?property .

  ?property a kwg-ont:ImpactObservableProperty .
  OPTIONAL { ?property rdfs:label ?propertyName }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?hurricaneLabel ?attributeType ?attributeLabel ?temporalData ?impactDetail
WHERE {
  # Identify Hurricane Events (Hurricane-specific hazards)
  ?hurricane a kwg-ont:NOAAHurricane .

  # Retrieve Hurricane Label
  ?hurricane rdfs:label ?hurricaneLabel .

  # Find Observations linked to the hurricane (Magnitude or Impact details)
  {
    ?obs sosa:hasFeatureOfInterest ?hurricane ;
         a kwg-ont:MagnitudeObservation ;
         sosa:observedProperty ?prop .
    BIND("Hazard Magnitude" AS ?attributeType)
  } UNION {
    ?obs sosa:hasFeatureOfInterest ?hurricane ;
         a kwg-ont:ImpactObservation ;
         sosa:observedProperty ?prop .
    BIND("Damage Impact" AS ?attributeType)
  }

  # Retrieve Attribute Labels (Observable Properties)
  ?prop rdfs:label ?attributeLabel .

  # Retrieve Temporal Data from Observation or Hazard Scope
  OPTIONAL { ?obs sosa:phenomenonTime ?temporalData }
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalData }

  # Retrieve Impact Details (Values) if available via Simple Result
  OPTIONAL { ?obs sosa:hasSimpleResult ?impactDetail }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?type ?deaths ?damage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attributeName ?healthValue
WHERE {
    ?place a kwgl-ont:Place .
    VALUES (?prop) { (kwgl-ont:percentDiabetic) (kwgl-ont:percentObese) }
    ?place ?prop ?healthValue .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?placeName ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  VALUES ?property {
    kwgl-ont:hasPopulation
    kwgl-ont:hasNumberOfHouseHolds
    kwgl-ont:percentDiabetic
    kwgl-ont:percentBelowPovertyLine
    kwgl-ont:percentObese
  }
  ?place ?property ?value .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardName (COUNT(?hazard) AS ?totalCount)
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL {
    ?hazard kwgl-ont:hasName ?hazardName .
  }
}
GROUP BY ?hazard ?hazardName

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?attribute (COUNT(*) AS ?numberOfAttributes) WHERE {
  kwgl-ont:Place ?attribute ?value .
  FILTER(CONTAINS(STR(?attribute), "Tornado"))
} GROUP BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?attributeName ?detailValue
WHERE {
  ?place a kwgl-ont:Place .

  # Storm Surges Attributes and Details
  OPTIONAL {
    { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?val } 
       UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?val }
     BIND("number of Storm Surges impacting Place / dollar damage of Storm Surges impacting Place" AS ?attributeName)
     BIND(?val AS ?detailValue)
  }

  # Hurricane Attributes and Details (Base + Years handled generally in UNION logic for brevity)
  OPTIONAL {
    { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?val } 
       UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?val }
     BIND("number of Hurricanes impacting Place / dollar damage of Hurricanes impacting Place" AS ?attributeName)
     BIND(?val AS ?detailValue)
  }

  # Tornado Attributes and Details (Base + Years handled generally in UNION logic for brevity)
  OPTIONAL {
    { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?val } 
       UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?val }
     BIND("number of Tornadoes impacting Place / dollar damage of Tornadoes impacting Place" AS ?attributeName)
     BIND(?val AS ?detailValue)
  }

  # Filter out NULL values generated by OPTIONALs to show only existing details
  FILTER(BOUND(?detailValue))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?area ?infraDamage ?cropDamage
WHERE {
    ?hazard rdf:type kwgl-ont:Earthquake .
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }
    OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
    OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
    OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
    OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?numberOfDeaths ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  {
    ?hazard kwgl-ont:affectedAreaInAcres ?value . BIND("affectedAreaInAcres" AS ?property)
  } UNION {
    ?hazard kwgl-ont:damageToCropsInDollars ?value . BIND("damageToCropsInDollars" AS ?property)
  } UNION {
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?value . BIND("damageToInfrastructureInDollars" AS ?property)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hurricane ?place ?startDate ?endDate ?affectedArea ?damageCrops ?damageInfra ?deaths ?dollarDamageOfHurricanesImpactingPlace ?numberOfHurricanesImpactingPlace
WHERE {
    ?hurricane rdf:type kwgl-ont:Hurricane .
    ?hurricane kwgl-ont:hasImpacted ?place .
    ?place rdf:type kwgl-ont:Place .

    OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?hurricane kwgl-ont:affectedAreaInAcres ?affectedArea }
    OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damageCrops }
    OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
    OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?deaths }

    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanesImpactingPlace }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?event ?eventName ?place ?placeName ?startDate ?endDate 
       ?hurricaneDamage ?tornadoDamage ?stormSurgeDamage ?infrastructureDamage ?cropDamage
WHERE {
    # Select Storm-specific Hazard Events
    { ?event rdf:type kwgl-ont:Hurricane }
    UNION 
    { ?event rdf:type kwgl-ont:Tornado }

    # Ensure temporal extent exists (start and end dates)
    ?event kwgl-ont:hasStartDate ?startDate .
    ?event kwgl-ont:hasEndDate ?endDate .

    # Optional Name for Event
    OPTIONAL { ?event kwgl-ont:hasName ?eventName }

    # Link to Geographical Place impacted
    ?event kwgl-ont:hasImpacted ?place .

    # Get Place Details
    ?place kwgl-ont:hasPlaceType ?placeType .
    OPTIONAL { ?place kwgl-ont:hasName ?placeName }

    # Retrieve Storm-Specific Damage Details (from Place, as per schema)
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?hurricaneDamage }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?tornadoDamage }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?stormSurgeDamage }

    # Retrieve General Damage Details (from Event)
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?className ?property ?value ?time
WHERE {
  ?hazard rdf:type ?className .
  ?className rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?time 
  }
  OPTIONAL { 
    ?hazard ?property ?value .
  }
}
ORDER BY ?hazard ?className ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a ?type .
  ?type rdfs:subClassOf* geo:Feature .
  OPTIONAL { ?place rdfs:label ?name }
}
ORDER BY ?place ?name

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?healthConcern ?concernType
WHERE {
  # Identify observation collections linked to geographical places (features)
  ?collection a sosa:ObservationCollection ;
              sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .

  # Retrieve the observed property from the collection or its members
  OPTIONAL { ?collection sosa:observedProperty ?healthConcern }
  OPTIONAL { 
    ?collection sosa:hasMember ?observation ;
                ?observation sosa:observedProperty ?healthConcern .
  }

  # Filter for health-related concern types (Public Health or Vulnerability)
  FILTER(
    EXISTS { ?healthConcern a kwg-ont:PublicHealthObservableProperty } ||
    EXISTS { ?healthConcern a kwg-ont:VulnerabilityObservableProperty }
  )

  # Bind type label for clarity
  BIND(
    IF(EXISTS { ?healthConcern a kwg-ont:PublicHealthObservableProperty }, "Public Health", 
       IF(EXISTS { ?healthConcern a kwg-ont:VulnerabilityObservableProperty }, "Social Vulnerability", "Health Related")) AS ?concernType)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?earthquakeHazard (SELECT (COUNT(DISTINCT ?hazard) WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Earthquake .
} AS ?totalCount)
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
}
ORDER BY ?earthquakeHazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?property (COUNT(DISTINCT ?property) OVER() AS ?totalAttributes) WHERE {
  # Identify the root class for tornado hazards as defined in the schema
  VALUES ?tornadoClass { kwg-ont:NOAATornado }

  # Match instances or subclasses of the Tornado hazard class to find associated attributes
  # We use a pattern that captures both direct types and subclasses if present in the graph structure
  FILTER EXISTS {
    { ?hazard a kwg-ont:NOAATornado . } UNION { ?hazard rdfs:subClassOf* kwg-ont:NOAATornado . }
  }

  # Retrieve attributes associated with these tornado hazard entities
  ?hazard ?property ?value .

  # Ensure properties are distinct and valid IRIs
  FILTER(isIRI(?property))
}
ORDER BY ?property ?totalAttributes

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attr ?type ?prop ?val
WHERE {
  # Retrieve storm-specific hazard attributes (Observable Properties)
  ?attr rdfs:type kwg-ont:StormTrackObservableProperty .
  UNION
  {
    ?attr rdfs:type kwg-ont:StormTrackletObservableProperty .
  }

  # Identify the specific type or category of the attribute if it has one
  OPTIONAL { ?attr rdfs:subClassOf* ?type . }
  OPTIONAL { ?attr rdfs:subClassOf ?supertype . }

  # Retrieve any additional details/properties for these attributes found in the schema
  OPTIONAL { 
    ?attr ?prop ?val .
    FILTER(?prop != rdfs:type)
  }
}
ORDER BY ?attr ?type ?prop ?val

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?floodType ?superType ?property ?value
WHERE {
  ?floodType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER(STR(?floodType) CONTAINS("Flood"))
  OPTIONAL { ?floodType rdfs:subClassOf ?superType . }
  OPTIONAL { ?floodType ?property ?value . }
}
ORDER BY ?floodType ?property ?value

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attributeName ?climateAttribute WHERE {
  ?climateAttribute rdf:type kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?climateAttribute rdfs:label ?attributeName }
}
ORDER BY ?attributeName

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?impactFactorName ?value
WHERE {
  ?collection rdf:type kwg-ont:ImpactObservationCollection .
  ?collection sosa:hasFeatureOfInterest ?hazardEvent .
  OPTIONAL {
    ?collection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?impactFactorName .
    OPTIONAL { ?observation sosa:resultValue ?value }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricaneType ?geoRelation ?geoValue ?impactDetail ?temporalData
WHERE {
  # Identify Hurricane Hazard entities (Classes and their hierarchy)
  ?hurricaneType rdfs:subClassOf* kwg-ont:NOAAHuranean .

  # Retrieve attributes related to a geographical place (Geometry, Spatial Relations)
  OPTIONAL { 
    ?hurricaneType kwg-ont:hasGeometry ?geoValue .
    FILTER(BOUND(?geoValue)) 
  }
  OPTIONAL { 
    ?hurricaneType geo:hasDefaultGeometry ?geoValue .
    FILTER(BOUND(?geoValue)) 
  }

  # Retrieve damage impact details linked to Hurricane observations (via Observation Collections)
  # Linking Hurricane Hazard Events to their Impact Observations and properties
  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricaneType .
    ?impactCollection a kwg-ont:ImpactObservationCollection .
    ?impactDetail sosa:observedProperty kwg-ont:ImpactObservableProperty .
  }

  # Retrieve temporal data associated with Hurricane hazards or their observations
  OPTIONAL { 
    ?hurricaneType kwg-ont:hasTemporalScope ?temporalData .
    FILTER(BOUND(?temporalData)) 
  }
  OPTIONAL {
    ?impactCollection sosa:phenomenonTime ?temporalData .
    FILTER(BOUND(?temporalData)) 
  }
}
ORDER BY ?hurricaneType ?geoRelation ?impactDetail
